def classify_open_json_reviewed_carriers(text, items, *, functions):
    """Exact reviewed remainder; JSON payloads never inherit their field key's ownership."""
    path = "FieldEvidenceApp/Infrastructure/Reporting/DeterministicOpenJSONRendererV1.swift"
    expected = REVIEWED_SWIFT_SOURCES[path]
    count, digest = ((35, "5c76f62b6f8db9f8d71aea35c15917f7dc0dba72736c3acd5d5f4ec050d44db7") if functions else
                     (199, "502f53e2319b80bed8561b5d3d124f6960a009eec480cfcc232fe6a7cebff013"))
    if sha(text.encode()) != expected or len(items) != count or sha(canonical(sorted(
            (i["kind"], i["locator"], i["sourceTextSHA256"]) for i in items))) != digest:
        raise ValueError("Reviewed OpenJSON carrier remainder changed")
    for item in items:
        if item["locator"] in OPEN_JSON_REVIEWED_UNKNOWN:
            continue
        report = item["locator"] in OPEN_JSON_REVIEWED_REPORT
        reason = ("OPEN_JSON_GENERATED_REPORT_VALUE: exact renderer-owned heading, separator or catalog label/state factory; lexical templates do not confer ownership on inserted source values. Pose text containing raw fallback or mixed source values remains separately unresolved."
                  if report else
                  "OPEN_JSON_CANONICAL_IDENTITY: reviewed schema/locale/hash/ID and closed raw-state fields, exact JSON-key and structured-header grammar, visible identity/digest functions, and canonical numeric formats. Canonical encoded nodes, generic text sinks and dictionaries with display payloads retain separate unresolved records.")
        item.update(classification="REPORT_EXPORT_CHROME" if report else "MACHINE_IDENTIFIER",
                    disposition="LOCALIZE_STABLE_KEY" if report else "PRESERVE_MACHINE_VALUE",
                    ownershipEvidence=reason, reviewedRecordSetSHA256=digest,
                    semanticReview={"sourceSHA256": expected, "rule": reason.split(":")[0]})
        if report:
            item["consumerChannels"] = ["REPORT_EXPORT"]

