def reviewed_metadata_items(path, raw, items):
    expected = REVIEWED_METADATA_SOURCES[path]
    if sha(raw) != expected:
        raise ValueError("Historical metadata source review is stale: " + path)
    document = json.loads(raw)
    name = path.rsplit("/", 1)[-1]
    for item in items:
        if item["kind"] != "JSON_STRING" or item["classification"] is not None:
            continue
        pointer = item["locator"]
        copy_source = False
        developer = False
        watermark = False
        locale = None
        if name == "UnsignedRCMetadataV1.json":
            copy_source = pointer in ("/app/candidateAppStoreTitle", "/app/currentDisplayName")
            developer = pointer.startswith("/nonClaims/")
        if name in ("DiscoveryTruthCatalogV1.json", "V23P04C26AcquisitionContentDraftV1.json"):
            match = re.fullmatch(r"/locales/(\d+)/(?:name|subtitle|description|keywords|promotionalText)", pointer)
            if match:
                copy_source = True
                locale = document["locales"][int(match[1])]["locale"]
        if name == "V23P04C26AcquisitionContentDraftV1.json":
            copy_source |= bool(re.fullmatch(r"/(?:control/copy|ppoHypotheses/\d+/copy|supportPageSpecs/\d+/(?:title|summary|limitations/\d+))", pointer))
        if name == "V23P04C27BrandHIGStateInventoryV1.json":
            copy_source = bool(re.fullmatch(r"/contracts/brandVocabularyMap/(?:genericShell/\d+|packageVocabulary/(?:LIGHTING|SIGNS|SURVEYS)/\d+|practice|product)", pointer))
            developer = pointer.startswith("/contracts/appIconReleaseManifest/blockingFindings/")
        if name == "V23P04C28BrandHIGSharedRootCorrectionLedgerV1.json":
            developer = bool(re.fullmatch(r"/(?:hostileAndInterruptionRecords/\d+/scenario|preservation/(?:publicCopyPolicy|technicalIdentityPolicy))", pointer))
        if name == "V23P04C15SyntheticSampleManifestV1.json":
            watermark = bool(re.fullmatch(r"/(?:defaultWatermark|practiceWatermark|samples/\d+/displayWatermarks/\d+)", pointer))
        if watermark:
            classification, disposition = "REPORT_EXPORT_CHROME", "SEPARATE_AUTHORITY_REQUIRED"
            rule = "FROZEN_SYNTHETIC_WARNING"
            evidence = "Hash-bound synthetic sample watermark is visible safety copy. Preserve this source and existing sample hashes; localized variants require new versioned artifacts and separate approval."
            item.update(preserveCanonicalSource=True, provenanceRole="FROZEN_SYNTHETIC_SAMPLE")
        elif copy_source:
            classification, disposition = "APP_OWNED_USER_FACING_COPY", "SEPARATE_AUTHORITY_REQUIRED"
            rule = "HISTORICAL_METADATA_DRAFT_COPY"
            evidence = "Explicit title, description, hypothesis, support or brand-vocabulary field is user-facing draft copy. Requires later locale research and brand/product/release authority; this historical record grants no publication or shipping credit."
            item.update(consumerChannels=["RELEASE_METADATA_OR_SUPPORT_DRAFT"],
                        sourceLocale=locale, languageCohortExpansionAuthorized=False,
                        shippingEligibility="HISTORICAL_DRAFT_NO_V30_RELEASE_CREDIT")
        elif developer:
            classification, disposition = "DEVELOPER_DEBUG_TEXT", "DEVELOPER_ONLY"
            rule = "HISTORICAL_METADATA_REVIEW_PROSE"
            evidence = "Developer checklist, diagnostic scenario or preservation-policy rationale; not published product copy."
        else:
            classification, disposition = "MACHINE_IDENTIFIER", "PRESERVE_MACHINE_VALUE"
            rule = "HISTORICAL_METADATA_CONTRACT_DATA"
            evidence = "Complete exact-source field review identifies schema/contract/claim IDs, refs, paths, hashes, selector/status tokens, source URLs, locale scopes and measurements; explicit copy and rationale fields have separate rules."
        item.update(classification=classification, disposition=disposition,
                    ownershipEvidence=rule + ": " + evidence,
                    semanticReview={"sourceSHA256": expected, "rule": rule})
    return items


def reviewed_resource_items(path, raw, items):
    if path in REVIEWED_METADATA_SOURCES:
        return reviewed_metadata_items(path, raw, items)
    expected = REVIEWED_RESOURCE_SOURCES.get(path)
    if expected is None:
        return items
    if sha(raw) != expected:
        raise ValueError("Structured-source semantic review is stale: " + path)
    for item in items:
        if item["classification"] is not None:
            continue
        pointer = item["locator"]
        if path == "Release/TestFlightExportOptions.plist":
            if item["kind"] != "PLIST_STRING" or pointer not in {"/destination", "/method", "/signingStyle"}:
                raise ValueError("Unexpected export-option text record: " + pointer)
            item.update(classification="MACHINE_IDENTIFIER", disposition="PRESERVE_MACHINE_VALUE",
                        ownershipEvidence="EXPORT_OPTION_MACHINE_VALUE: destination, method and signingStyle are export/signing configuration tokens in the exact plist copied into EXPORT_OPTIONS_PATH by the historical TestFlight workflow. They are tool inputs, not app or store copy. Inventory classification grants no execution or release authority.",
                        semanticReview={"sourceSHA256": expected, "rule": "EXPORT_OPTION_MACHINE_VALUE"})
            continue
        if path.endswith("StarterWorkspaceTemplateV1.json") and pointer == "/practiceWatermark":
            item.update(classification="REPORT_EXPORT_CHROME", disposition="SEPARATE_AUTHORITY_REQUIRED",
                        ownershipEvidence="CANONICAL_PRACTICE_WARNING: visible report watermark participates in the template hash and exact validation. Preserve existing bytes; a separately versioned presentation/reconciliation decision is required before changing language.",
                        consumerChannels=["APP_UI", "REPORT_EXPORT"],
                        consumerEvidence=["FieldEvidenceApp/Domain/WorkspaceExperience/WorkspaceExperienceContractsV1.swift:206-245",
                                          "FieldEvidenceApp/Infrastructure/Reporting/WorklightPDFRendererV1.swift:257-262"],
                        preserveCanonicalSource=True,
                        semanticReview={"sourceSHA256": expected, "rule": "CANONICAL_PRACTICE_WARNING"})
            continue
        if path.endswith("/Packs/IlluminatedSignPack.json"):
            machine = re.fullmatch(r"/(?:packID|evidencePurposes/\d+/key|acknowledgements/\d+/(?:key|version)|"
                                   r"issueLabels/\d+/key|couldNotVerifyReasons/(?:version|entries/\d+/key)|"
                                   r"stageDisplays/\d+/key|outcomeDisplays/\d+/key)", pointer)
            copy_field = re.fullmatch(r"/(?:nouns/(?:asset|check|issue)/(?:singular|plural)|"
                                      r"evidencePurposes/\d+/(?:display|instruction)|acknowledgements/\d+/copy|"
                                      r"issueLabels/\d+/display|couldNotVerifyReasons/entries/\d+/display|"
                                      r"stageDisplays/\d+/display|outcomeDisplays/\d+/display|disclaimer)", pointer)
            if machine:
                item.update(classification="MACHINE_IDENTIFIER", disposition="PRESERVE_MACHINE_VALUE",
                            ownershipEvidence="BUNDLED_PACK_IDENTITY: loader and shipping adapter preserve exact pack/registry keys and content-version identities.")
            elif copy_field:
                # This frozen shipping pack is app-controlled; no administrator
                # editing route is proven. Do not exclude it as authored user
                # content merely because its values are packaged in JSON.
                professional = pointer in ("/disclaimer", "/acknowledgements/1/copy")
                item.update(classification="LEGAL_LICENSED_JURISDICTION" if professional else "APP_OWNED_USER_FACING_COPY",
                            disposition="SEPARATE_AUTHORITY_REQUIRED" if professional else "LOCALIZE_STABLE_KEY",
                            ownershipEvidence="BUNDLED_APP_PACK_PRESENTATION: app-controlled nouns, labels and instructions flow through ShippingIlluminatedSignAdapterV1 to UI and report snapshots. Localization must derive presentation while preserving frozen pack parity and historical evidence; safety acknowledgement/disclaimer need professional review.",
                            preserveCanonicalSource=True,
                            consumerChannels=["APP_UI"] if pointer.endswith("/instruction") else ["APP_UI", "REPORT_EXPORT"],
                            consumerEvidence=["FieldEvidenceApp/Domain/Packs/SignPackLoader.swift:18-25",
                                              "FieldEvidenceApp/Infrastructure/Packs/ShippingIlluminatedSignAdapterV1.swift:70-139",
                                              "FieldEvidenceApp/Infrastructure/Reporting/WorklightPDFRendererV1.swift:276-330"])
            else:
                continue
            item["semanticReview"] = {"sourceSHA256": expected, "rule": "BUNDLED_PACK_IDENTITY" if machine else "BUNDLED_APP_PACK_PRESENTATION"}
            continue
        if path.endswith("Info.plist") and not re.fullmatch(
                r"/(?:FieldEvidenceIncumbentFileAdapterStatus|UISupportedInterfaceOrientations/[012]|"
                r"UTExportedTypeDeclarations/[0-3]/(?:UTTypeConformsTo/0|UTTypeIdentifier|"
                r"UTTypeTagSpecification/public\.(?:filename-extension/0|mime-type))|"
                r"CFBundleDocumentTypes/0/(?:CFBundleTypeExtensions/0|CFBundleTypeMIMETypes/0|"
                r"CFBundleTypeRole|LSHandlerRank|LSItemContentTypes/0))", pointer):
            continue
        item.update(classification="MACHINE_IDENTIFIER", disposition="PRESERVE_MACHINE_VALUE",
                    ownershipEvidence="REVIEWED_RESOURCE_FIELD: exact frozen schema/configuration ID, enum, localization reference or digest; the referenced display producer is separately inventoried.",
                    semanticReview={"sourceSHA256": expected, "rule": "REVIEWED_RESOURCE_FIELD"})
        if path.endswith(("ContextualGuidanceCatalogV1.json", "ProductChangeCatalogV1.json", "StarterWorkspaceTemplateV1.json")) and pointer.endswith(("/titleKey", "/bodyKey", "/actionKey")):
            item["consumerResolution"] = "NO_RENDERING_BINDING_PROVEN; stable key identity only, no current catalog-resolution or UI-adoption claim."
    return items


def masked_swift(text, spans):
    """Hide literal payloads, retaining executable interpolation expressions."""
    masked = list(text)
    for span in spans:
        cursor = span["start"]
        regions = []
        for begin, end in span.get("interpolations", []):
            expression_start = begin + 2 + span["rawHashes"]
            regions.append((cursor, expression_start))
            cursor = end - 1
        regions.append((cursor, span["end"]))
        for begin, end in regions:
            for at in range(begin, end):
                if masked[at] != "\n":
                    masked[at] = " "
    return "".join(masked)


def delimited_end(code, opening):
    pairs = {"(": ")", "[": "]", "{": "}"}
    stack = [pairs[code[opening]]]
    for at in range(opening + 1, len(code)):
        char = code[at]
        if char in pairs:
            stack.append(pairs[char])
        elif char in ")]}":
            if char != stack.pop():
                raise ValueError("Mismatched Swift source delimiters")
            if not stack:
                return at + 1
    raise ValueError("Unterminated Swift source delimiter")


def call_arguments(code, names):
    """Split only top-level arguments; commas in literals/closures stay inside.

    This records source syntax, not overload resolution. Semantic rules below
    are limited to exact reviewed source hashes and known call signatures.
    """
    calls = []
    pattern = r"\b(" + "|".join(sorted(names)) + r")\s*\("
    for match in re.finditer(pattern, code):
        if re.search(r"\bfunc\s+$", code[max(0, match.start() - 20):match.start()]):
            continue
        opening = match.end() - 1
        end = delimited_end(code, opening)
        start, at, arguments = opening + 1, opening + 1, []
        while at < end - 1:
            if code[at] in "([{":
                at = delimited_end(code, at)
                continue
            if code[at] == ",":
                arguments.append((start, at))
                start = at + 1
            at += 1
        if start < end - 1:
            arguments.append((start, end - 1))
        calls.append({"name": match[1], "start": match.start(), "end": end,
                      "arguments": arguments})
    return calls


