def classify_reviewed_c52_contact_tokens(path, text, items):
    reviewed = REVIEWED_C52_CONTACT_TOKEN_PAIRS.get(path)
    if reviewed is None:
        return
    expected, locators, digest = reviewed
    if sha(text.encode()) != expected:
        raise ValueError("Reviewed C52 contact-token source changed: " + path)
    selected = [item for item in items if item["locator"] in locators]
    if len(selected) != 2 or sha(canonical(sorted(
            (i["kind"], i["locator"], i["sourceTextSHA256"]) for i in selected))) != digest:
        raise ValueError("Reviewed C52 contact-token pair changed: " + path)
    for item in selected:
        if item["classification"] is not None:
            raise ValueError("C52 contact-token ownership changed before independent review: " + path)
        item.update(classification="MACHINE_IDENTIFIER", disposition="PRESERVE_MACHINE_VALUE",
                    ownershipEvidence="C52_CLOSED_CONTACT_ASSERTION_TOKEN: exact static boundary declaration and literal mirror ServiceRequestContactAssertionV1.unverifiedWording. Its validator admits only SELF_ASSERTED_UNVERIFIED and its decoder requires the wording field; app/test source review finds no consumers of these boundary constants. This is protocol identity, not contact value or display prose.",
                    reviewedRecordSetSHA256=digest,
                    semanticReview={"sourceSHA256": expected, "rule": "C52_CLOSED_CONTACT_ASSERTION_TOKEN"})


