def canonical(value):
    return (json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode()


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def seal(value):
    value["payloadDigest"] = sha(canonical({k: v for k, v in value.items() if k != "payloadDigest"}))
    return value


def git(*args):
    return subprocess.check_output(["git", "-C", str(ROOT), *args])


def source_tree():
    """Read Git objects, not arbitrary paths or another worktree."""
    result = []
    for entry in git("ls-tree", "-rz", BASE).split(b"\0"):
        if not entry:
            continue
        header, path = entry.split(b"\t", 1)
        mode, kind, oid = header.decode().split()
        if kind != "blob":
            raise ValueError("Unsupported tree entry: " + path.decode())
        result.append((path.decode(), mode, oid))
    return result


def source_blobs(tree):
    # One bounded Git process avoids thousands of subprocesses.
    process = subprocess.run(
        ["git", "-C", str(ROOT), "cat-file", "--batch"],
        input=("".join(oid + "\n" for _, _, oid in tree)).encode(),
        stdout=subprocess.PIPE, check=True,
    )
    output, cursor, values = process.stdout, 0, {}
    for path, mode, oid in tree:
        boundary = output.index(b"\n", cursor)
        header = output[cursor:boundary].decode().split()
        if header[:2] != [oid, "blob"]:
            raise ValueError("Git object identity mismatch")
        length = int(header[2])
        start = boundary + 1
        raw = output[start:start + length]
        if len(raw) != length or output[start + length:start + length + 1] != b"\n":
            raise ValueError("Truncated Git blob")
        values[path] = raw
        cursor = start + length + 1
    if cursor != len(output):
        raise ValueError("Unexpected trailing Git output")
    return values


class SwiftLexer:
    """Recognize comments and literal boundaries, including interpolation.

    Offsets are Unicode code-point positions in the exact decoded Git blob.
    Nested interpolated string tokens are retained separately from their
    containing template. No regex match is used to terminate a Swift string.
    """
    def __init__(self, text):
        self.text = text
        self.spans = []
        self.words = []

    def scan(self):
        self.code(0)
        return sorted(self.spans, key=lambda x: (x["start"], -x["end"], x["kind"]))

    def emit(self, start, end, kind, **extra):
        self.spans.append(dict(start=start, end=end, kind=kind, **extra))

    def code(self, pos, interpolation=False):
        text, length, depth = self.text, len(self.text), 1 if interpolation else 0
        while pos < length:
            if interpolation and text.startswith('\\"', pos):
                # Preserve observed source spelling rather than silently
                # dropping a field when an interpolation uses escaped quotes.
                # This is a lexical observation, not Swift compiler approval.
                start = pos
                end = text.find('\\"', pos + 2)
                if end < 0:
                    raise ValueError("Unterminated escaped interpolation token")
                pos = end + 2
                self.emit(start, pos, "SWIFT_ESCAPED_INTERPOLATION_TOKEN")
                continue
            if text.startswith("//", pos):
                end = text.find("\n", pos)
                if end < 0:
                    end = length
                self.emit(pos, end, "SWIFT_COMMENT")
                pos = end
                continue
            if text.startswith("/*", pos):
                start, nesting = pos, 1
                pos += 2
                while pos < length and nesting:
                    if text.startswith("/*", pos):
                        nesting += 1
                        pos += 2
                    elif text.startswith("*/", pos):
                        nesting -= 1
                        pos += 2
                    else:
                        pos += 1
                if nesting:
                    raise ValueError("Unterminated block comment at " + str(start))
                self.emit(start, pos, "SWIFT_COMMENT")
                continue
            match = STRING_START.match(text, pos)
            if match:
                pos = self.string(pos, len(match[1]), match[2])
                continue
            # Extended Swift regex delimiters have distinct ownership.
            match = REGEX_START.match(text, pos)
            if match:
                start, hashes = pos, match[1]
                closing = "/" + hashes
                end = text.find(closing, pos + len(hashes) + 1)
                if end < 0:
                    raise ValueError("Unterminated extended regex")
                pos = end + len(closing)
                self.emit(start, pos, "SWIFT_REGEX")
                continue
            if interpolation:
                if text[pos] == "(":
                    depth += 1
                elif text[pos] == ")":
                    depth -= 1
                    if depth == 0:
                        return pos + 1
            word = WORD.match(text, pos)
            if word:
                self.words.append((pos, pos + len(word[0]), word[0]))
                pos += len(word[0])
            else:
                pos += 1
        if interpolation:
            raise ValueError("Unterminated string interpolation")
        return pos

    def string(self, start, hashes, quote):
        text = self.text
        opening = "#" * hashes + quote
        closing = quote + "#" * hashes
        escape = "\\" + "#" * hashes
        pos = start + len(opening)
        interpolations = []
        while pos < len(text):
            if len(quote) == 1 and text[pos] in "\r\n":
                raise ValueError("Newline in single-line string at " + str(start))
            if text.startswith(closing, pos):
                end = pos + len(closing)
                self.emit(start, end, "SWIFT_STRING", rawHashes=hashes,
                          multiline=len(quote) == 3, interpolations=interpolations)
                return end
            if text.startswith(escape + "(", pos):
                begin = pos
                pos = self.code(pos + len(escape) + 1, interpolation=True)
                interpolations.append([begin, pos])
                continue
            if text.startswith(escape, pos):
                pos += len(escape) + 1
                continue
            pos += 1
        raise ValueError("Unterminated string at " + str(start))


def is_test(path):
    return path.startswith(("FieldEvidenceAppTests/", "FieldEvidenceAppUITests/",
                            "TestFixtures/", "TestSupport/", "TestPlans/"))


def role_for(path):
    if is_test(path):
        return "TEST_OWNER"
    if path.startswith("FieldEvidenceApp/Features/"):
        return "FEATURE_UI_OWNER"
    if path.startswith("FieldEvidenceApp/Domain/"):
        return "DOMAIN_CONTRACT_OWNER"
    if path.startswith("FieldEvidenceApp/Infrastructure/"):
        return "INFRASTRUCTURE_ADAPTER_OWNER"
    if path.startswith("FieldEvidenceApp/Resources/"):
        return "BUNDLED_CONTENT_OWNER"
    if path.startswith("Release/") or path.startswith("docs/product/"):
        return "RELEASE_METADATA_OWNER"
    return "SOURCE_FILE_OWNER"


def fixed_class(path, kind, prefix="", value="", locator=""):
    if is_test(path):
        return "DEVELOPER_DEBUG_TEXT", "TEST_ONLY", "Explicit test/support source path."
    if kind in ("SWIFT_COMMENT", "DEVELOPER_DOCUMENT"):
        return "DEVELOPER_DEBUG_TEXT", "DEVELOPER_ONLY", "Comment or non-runtime developer document."
    if kind == "METADATA_DOCUMENT_LINE" and path in REVIEWED_DEVELOPER_DOCUMENTS:
        return "DEVELOPER_DEBUG_TEXT", "DEVELOPER_ONLY", REVIEWED_DEVELOPER_DOCUMENTS[path]
    if kind == "SWIFT_STRING" and value.startswith('"') and value.endswith('"') and value[1:-1] in CATALOG_KEYS:
        return "MACHINE_IDENTIFIER", "PRESERVE_MACHINE_VALUE", "Exact reference to a frozen catalog key; visible catalog value and rendering call are separately inventoried."
    if kind in ("JSON_KEY", "PLIST_KEY", "SWIFT_REGEX", "PROJECT_CONFIGURATION"):
        return "MACHINE_IDENTIFIER", "PRESERVE_MACHINE_VALUE", "Schema/configuration identity or parser grammar."
    if path.endswith(".xcstrings"):
        if locator.endswith("/stringUnit/value"):
            return ("ACCESSIBILITY_TEXT" if "accessibility" in locator else "APP_OWNED_USER_FACING_COPY",
                    "LOCALIZE_STABLE_KEY", "Bundled catalog string-unit value; identity remains separately preserved.")
        return "DEVELOPER_DEBUG_TEXT", "DEVELOPER_ONLY", "Catalog developer metadata, state or locale identity."
    if path.endswith("Info.plist") and any(key in locator for key in (
            "UsageDescription", "UTTypeDescription", "CFBundleTypeName")):
        return "APP_OWNED_USER_FACING_COPY", "LOCALIZE_STABLE_KEY", "User-visible permission or document-type description."
    if path.endswith((".xcprivacy", ".entitlements")):
        return "MACHINE_IDENTIFIER", "PRESERVE_MACHINE_VALUE", "Apple privacy/capability schema."
    if "/Assets.xcassets/" in path:
        return "MACHINE_IDENTIFIER", "PRESERVE_MACHINE_VALUE", "Asset definition metadata, not visible text."
    if MACHINE_PARAMETER.search(prefix):
        return "MACHINE_IDENTIFIER", "PRESERVE_MACHINE_VALUE", "Explicit identifier, key, path or system-symbol argument."
    if re.search(r"\bcase\s+\w+\s*=\s*$", prefix):
        return "MACHINE_IDENTIFIER", "PRESERVE_MACHINE_VALUE", "Swift enum raw value; rendered projection requires a separate record."
    if re.search(r"\b(?:let|var)\s+\w*(?:Identifier|ID|Key|Path|Digest|SHA256)\s*=\s*$", prefix):
        return "MACHINE_IDENTIFIER", "PRESERVE_MACHINE_VALUE", "Explicit machine-identity declaration."
    if re.search(r"\.(accessibilityLabel|accessibilityHint|accessibilityValue|accessibilityInputLabels)\(\s*$", prefix):
        return "ACCESSIBILITY_TEXT", "LOCALIZE_STABLE_KEY", "Literal accessibility presentation argument."
    if re.search(r"(?:\bText|\bButton|\bLabel|\bSection|\bToggle|\bPicker|\bTextField|"
                 r"\bDatePicker|\bLink|\bDisclosureGroup|\bnavigationTitle|\bconfirmationDialog|\balert)\(\s*$", prefix):
        return "APP_OWNED_USER_FACING_COPY", "LOCALIZE_STABLE_KEY", "Literal argument at an app presentation call."
    return None, "SEMANTIC_REVIEW_REQUIRED", "Producer/consumer ownership must be resolved before inventory acceptance."


def make_item(path, locator, kind, value, prefix="", **extra):
    classification, disposition, reason = fixed_class(path, kind, prefix, value, locator)
    item = {
        "id": sha((path + "\0" + kind + "\0" + locator).encode())[:24],
        "locator": locator, "kind": kind,
        "recordRole": RECORD_ROLES[kind],
        "sourceTextSHA256": sha(value.encode()),
        "preview": value[:180],
        "owner": role_for(path),
        "classification": classification, "disposition": disposition,
        "ownershipEvidence": reason,
        **extra,
    }
    if kind == "SWIFT_ESCAPED_INTERPOLATION_TOKEN":
        item["syntaxObservation"] = "Escaped quote spelling inside interpolation; lexical capture only, requires native compiler qualification."
    if path == "FieldEvidenceApp/Features/Settings/EraseAllView.swift":
        if value == '"ERASE"':
            item.update(classification="MACHINE_IDENTIFIER", disposition="PRESERVE_MACHINE_VALUE",
                        ownershipEvidence="EraseAllService.requiredConfirmation defines the exact case-sensitive ERASE token; surrounding UI is separate.")
        elif "ERASE" in value:
            item["protectedTokens"] = ["ERASE"]
        if extra.get("symbol") == "errorMessage" or (kind == "TEXT_PRESENTATION_CALL" and "Text(errorMessage)" in value):
            item.update(classification="OBSOLETE_UNREACHABLE", disposition="OBSOLETE_UNREACHABLE",
                        ownershipEvidence="State is nil/unassigned; erase failures invoke onFailure instead. Source trace: declaration line30, render85-93, reset144, failure178-180.")
    if path == "FieldEvidenceApp/Infrastructure/Deletion/EraseAllService.swift" and value == '"ERASE"':
        item.update(classification="MACHINE_IDENTIFIER", disposition="PRESERVE_MACHINE_VALUE",
                    ownershipEvidence="requiredConfirmation at513-516 and equality enforcement615-617 define a case-sensitive command token.")
    return item


def classify_reviewed_dictionary_text(path, text, items):
    """Classify both sides of explicitly reviewed dictionary carriers."""
    reviews = {
        "FieldEvidenceApp/Domain/Drafts/FieldDraftContractsV1.swift": (
            "19705f38165e97015ba14bd8d0b4b0e75f004126c5300ac8f03f30df559e2f36",
            2, "5fb1d8f260362113a9056e722dbe3a90db24a3820bc96aba774cd6d2100ee3ef",
            "DRAFT_CONSUMED_CONTENT_DICTIONARY: receipt construction and restore rebinding carry stage UUID string keys to content-ID string values. Recovery and writer rebuild the same map from reservations; restore parses each key as UUID, remaps the stage identity and preserves its content ID. Both sides are identities, independently of attachment content bytes."),
        "FieldEvidenceApp/Infrastructure/Drafts/DraftCommitSagaRecoveryV1.swift": (
            "e275de58f9c327f323435aacbe75854aa27e0a5640f4d4857528f0b8c7b6e508",
            1, "be2fe25778d5da8887011193ab8a030b2eb6276f6a56bb90d6f723a8a0821b16",
            "DRAFT_RECOVERY_CONTENT_DICTIONARY: consumedContent filters reservations by workspace/draft/plan, verifies unique stage IDs and expected count, and returns stageID.uuidString mapped to locator.contentID. Exact dictionary equality checks the recorded receipt; neither side carries attachment prose."),
        "FieldEvidenceApp/Infrastructure/Persistence/WorkspaceWriterAdapterV1.swift": (
            "84cc28ffe7b87eee1459002852a04f8cca701af8726a94ca5bf032e0407759a1",
            1, "21d22a4608e0ee3b7fc1e87d59e56f03ae32be88f2fa63dd5fa90c0bdc1a13ac",
            "DRAFT_WRITER_CONTENT_DICTIONARY: fieldDraftConsumedContent returns the unique stage UUID string to locator content-ID map from validated reservation rows bound to the exact workspace/draft/plan. Content identifiers remain separate from content bytes."),
        "FieldEvidenceApp/Domain/Models/WorkResourcePersistenceModelsV1.swift": (
            "b31070c72cdb9b91395f1bf3e2ad7f294c45073676454233a493cfb292096cfa",
            3, "c3b90fc47362fe499939a153e69a81cb083c9e722c1cbbf216f95ecb32f0bacc",
            "WORK_RESOURCE_CURRENCY_DICTIONARY: totals validation and both projection constructors carry currency-code keys to Int64 cost mantissas. The domain projection groups costs by amount.currencyCode, and persistence preserves those separate currency partitions without conversion. This is a semantic key role, not a claim that the convenience inputs validate ISO membership. Material descriptions and unit prose are separate fields."),
        "FieldEvidenceApp/Infrastructure/Packs/ShippingIlluminatedSignAdapterV1.swift": (
            "50157cc98486db6a567980bc4c476e11b8675f39b834def0cca333ed4fa29a0b",
            1, "b9197bf8feb01fcdb69e9f965c42f7339fd17722a5d6c114368611a9da313f22",
            "SIGN_ACKNOWLEDGEMENT_DICTIONARY: acknowledgementValues maps sign-pack acknowledgement lookup keys to booleans. typedResponses requires every key in the pack key set and maps values to typed boolean responses under legacy acknowledgement field IDs. Acknowledgement display wording is a separate source."),
    }
    review = reviews.get(path)
    if review is None:
        return
    expected, count, digest, evidence = review
    selected = [i for i in items if i.get("textTypeShape") == "DICTIONARY"]
    if sha(text.encode()) != expected:
        raise ValueError("Reviewed dictionary source changed: " + path)
    if len(selected) != count or sha(canonical(sorted(
            (i["kind"], i["locator"], i["sourceTextSHA256"]) for i in selected))) != digest:
        raise ValueError("Reviewed dictionary record set changed: " + path)
    for item in selected:
        if item["classification"] is not None or item["disposition"] != "SEMANTIC_REVIEW_REQUIRED":
            raise ValueError("Dictionary already has independent ownership: " + path)
        item.update(classification="MACHINE_IDENTIFIER", disposition="PRESERVE_MACHINE_VALUE",
                    ownershipEvidence=evidence, reviewedRecordSetSHA256=digest,
                    semanticReview={"sourceSHA256": expected, "rule": evidence.split(":", 1)[0]})


