def classify_reviewed_catalog_adapters(path, text, items):
    """Keep generic mixed catalog carriers separate from closed display adapters."""
    if path != "FieldEvidenceApp/Infrastructure/Localization/BundledLocalizationCatalogV1.swift":
        return
    expected = "c52cfb7a59f8a016c0a5b4dfb9e2b55a09ec73a94411eb3f09e1039c05ca5788"
    digest = "89387f10997ef3c57e635fe311388716a706df90ee2ce7ce90dd94ce5267da9c"
    selected = [i for i in items if i["locator"] in CATALOG_ADAPTER_REVIEW_LOCATORS]
    if sha(text.encode()) != expected:
        raise ValueError("Reviewed catalog adapter source changed")
    if len(selected) != 66 or sha(canonical(sorted(
            (i["kind"], i["locator"], i["sourceTextSHA256"]) for i in selected))) != digest:
        raise ValueError("Reviewed catalog adapter record set changed")
    if any(i["classification"] is not None or i["disposition"] != "SEMANTIC_REVIEW_REQUIRED" for i in selected):
        raise ValueError("Catalog adapter already has independent ownership")
    for item in selected:
        if item["locator"] in {"function-return:162881", "function-parameter:230017",
                               "function-return:249576", "function-return:249839"}:
            # The generic localized return and definition value both include
            # packageAuthorizedPosition's separately reviewed legal/safety copy.
            # The C03 playbook wrappers likewise include the safe-position
            # instruction and non-certification disclaimer. A closed key
            # universe does not imply a single ownership class.
            continue
        assertion = item["kind"] == "SWIFT_STRING"
        evidence = (
            "CATALOG_DEFAULT_ASSERTION: exact English catalog messages used by local portable-review and file-save validation assertions. They mirror app-authored defaults, not runtime user responses or capability bytes. This record does not authorize changing the validation invariant."
            if assertion else
            "CLOSED_CATALOG_ADAPTER_RETURN: exact typed-key English/default or localized factories and their state-to-key wrappers return app-authored display vocabulary. The narrowed key families exclude packageAuthorizedPosition; forwarding through the generic bundled switch preserves that restriction. Localized factories bind catalog keys and English defaults; no arbitrary user text is supplied. The generic mixed localized return and definition-value parameter retain independent unresolved records.")
        item.update(classification="APP_OWNED_USER_FACING_COPY", disposition="LOCALIZE_STABLE_KEY",
                    ownershipEvidence=evidence, reviewedRecordSetSHA256=digest,
                    semanticReview={"sourceSHA256": expected, "rule": evidence.split(":", 1)[0]})


