def dictionary_text_type_end(code, start, *, supplemental=False):
    """Recognize explicit dictionary text carriers; return their exact type end.

    Bracket and standard-library collection spellings may nest. Nominal leaf
    types are retained without inferring their contents. Aliases, arbitrary
    generic wrappers, tuples and closures need separate coverage.
    Supplemental parsing permits Set and non-dictionary carriers, then the
    caller removes every type already covered by a prior census partition.
    """
    name = re.compile(r"(?:`[^`\r\n]+`|[^\W\d]\w*)(?:\s*\.\s*(?:`[^`\r\n]+`|[^\W\d]\w*))*")
    text_names = {"String", "Swift.String", "LocalizedStringKey", "SwiftUI.LocalizedStringKey"}
    wrappers = {"Dictionary": 2, "Swift.Dictionary": 2, "Array": 1,
                "Swift.Array": 1, "Optional": 1, "Swift.Optional": 1}
    if supplemental:
        wrappers.update({"Set": 1, "Swift.Set": 1})

    def skip(at):
        while at < len(code) and code[at].isspace():
            at += 1
        return at

    def parse(at):
        at = skip(at)
        has_text = has_dictionary = False
        if code[at:at + 1] == "[":
            child = parse(at + 1)
            if child is None:
                return None
            at, has_text, has_dictionary = child
            at = skip(at)
            if code[at:at + 1] == ":":
                child = parse(at + 1)
                if child is None:
                    return None
                at, child_text, _ = child
                has_text |= child_text
                has_dictionary = True
                at = skip(at)
            if code[at:at + 1] != "]":
                return None
            at += 1
        else:
            matched = name.match(code, at)
            if matched is None:
                return None
            spelling = re.sub(r"\s+", "", matched[0])
            at = matched.end()
            has_text = spelling in text_names
            generic_at = skip(at)
            if code[generic_at:generic_at + 1] == "<":
                arity = wrappers.get(spelling)
                if arity is None:
                    return None
                at = generic_at + 1
                for index in range(arity):
                    child = parse(at)
                    if child is None:
                        return None
                    at, child_text, child_dictionary = child
                    has_text |= child_text
                    has_dictionary |= child_dictionary
                    at = skip(at)
                    if index + 1 < arity:
                        if code[at:at + 1] != ",":
                            return None
                        at += 1
                if code[at:at + 1] != ">":
                    return None
                at += 1
                has_dictionary |= arity == 2
        suffix = skip(at)
        if code[suffix:suffix + 1] in {"?", "!"}:
            at = suffix + 1
        suffix = skip(at)
        if code.startswith("...", suffix):
            at = suffix + 3
        return at, has_text, has_dictionary

    parsed = parse(start)
    return parsed[0] if parsed and parsed[1] and (parsed[2] or supplemental) else None


DIRECT_TEXT_TYPE = re.compile(
    r"(?:(?:(?:Swift\.)?String|(?:SwiftUI\.)?LocalizedStringKey)\b|"
    r"\[\s*(?:(?:Swift\.)?String|(?:SwiftUI\.)?LocalizedStringKey)\b\s*\])(?:\s*(?:[?!]|\.\.\.))?")


def collection_text_type_end(code, start):
    """Supplement standard wrappers without changing prior census partitions.

    Includes explicit Set/Array/Optional and nested bracket arrays, including
    Set-containing dictionaries. Direct and older dictionary records keep their
    original identity, review guards and shape. Nominal contents are not inferred.
    """
    end = dictionary_text_type_end(code, start, supplemental=True)
    if (end is None or dictionary_text_type_end(code, start) == end
            or DIRECT_TEXT_TYPE.fullmatch(code[start:end])):
        return None
    return end


# Swift lexical operator-head/operator-character grammar, including combining
# marks only after a head and dots only in dot-leading operators. This records
# lexical declarations; fixity, reserved-token and overload legality stay native.
# Source: https://docs.swift.org/swift-book/documentation/the-swift-programming-language/lexicalstructure/#Operators
SWIFT_OPERATOR_HEAD_CHARS = (
    r"/=+\-!*%<>&|^~?\u00a1-\u00a7\u00a9\u00ab\u00ac\u00ae\u00b0-\u00b1"
    r"\u00b6\u00bb\u00bf\u00d7\u00f7\u2016-\u2017\u2020-\u2027"
    r"\u2030-\u203e\u2041-\u2053\u2055-\u205e\u2190-\u23ff"
    r"\u2500-\u2775\u2794-\u2bff\u2e00-\u2e7f\u3001-\u3003\u3008-\u3020\u3030"
)
SWIFT_OPERATOR_CONTINUATION_CHARS = (
    SWIFT_OPERATOR_HEAD_CHARS
    + r"\u0300-\u036f\u1dc0-\u1dff\u20d0-\u20ff\ufe00-\ufe0f\ufe20-\ufe2f"
    + "\U000e0100-\U000e01ef"
)
SWIFT_OPERATOR_PATTERN = (
    "(?:[" + SWIFT_OPERATOR_HEAD_CHARS + "][" + SWIFT_OPERATOR_CONTINUATION_CHARS + "]*"
    + r"|\.[." + SWIFT_OPERATOR_CONTINUATION_CHARS + "]+)"
)


