def typealias_outer_element_spans(code, opening, closing):
    """Split an alias's outer tuple; never split inside a nested carrier."""
    begin, cursor, angle_depth, spans = opening + 1, opening + 1, 0, []
    while cursor < closing:
        char = code[cursor]
        if char in "([{":
            cursor = delimited_end(code, cursor)
            continue
        if char == "<":
            angle_depth += 1
        elif char == ">" and code[cursor - 1] != "-":
            angle_depth -= 1
        elif char == "," and angle_depth == 0:
            spans.append((begin, cursor))
            begin = cursor + 1
        cursor += 1
    spans.append((begin, closing))
    return spans


def typealias_tuple_text_declarations(path, text, code, newlines):
    """Record direct text elements of nongeneric tuple aliases independently."""
    result = []
    name = r"(`[^`\r\n]+`|[^\W\d]\w*)"
    for match in re.finditer(r"\btypealias\s+" + name + r"\s*=\s*(?=\()", code):
        opening = match.end()
        closing = delimited_end(code, opening) - 1
        suffix = code[closing + 1:]
        boundary = suffix.lstrip()
        whitespace = suffix[:len(suffix) - len(boundary)]
        if (boundary.startswith(("->", ".", "?", "!", "&"))
                or re.match(r"(?:async|throws|rethrows)\b", boundary)):
            continue
        if boundary and not (boundary.startswith((";", "}")) or "\n" in whitespace):
            continue
        spans = typealias_outer_element_spans(code, opening, closing)
        if len(spans) < 2:
            continue  # A parenthesized single type is not a tuple.
        for index, (begin, end) in enumerate(spans):
            while begin < end and code[begin].isspace():
                begin += 1
            label = re.match(name + r"\s*:\s*", code[begin:end])
            if label:
                begin += label.end()
            while end > begin and code[end - 1].isspace():
                end -= 1
            if not DIRECT_TEXT_TYPE.fullmatch(code[begin:end]):
                continue
            line = bisect.bisect_left(newlines, begin)
            result.append(make_item(
                path, f"typealias-tuple-element:{begin}",
                "TYPEALIAS_TUPLE_TEXT_ELEMENT_DECLARATION", text[begin:end],
                line=line, column=begin - newlines[line - 1],
                typealiasSymbol=match[1], elementIndex=index,
                **({"elementLabel": label[1]} if label else {}),
                classification=None, disposition="SEMANTIC_REVIEW_REQUIRED",
                ownershipEvidence="Tuple-alias element has no independent producer/consumer ownership proof yet.",
                ownershipBoundary="Each explicit tuple-alias text element carries its own value. Neighboring tuple elements, field labels and enclosing report code do not establish ownership of this element."))
    return result


def typealias_closure_text_declarations(path, text, code, newlines):
    """Supplement direct closure-alias inputs without inheriting old reviews.

    This recognizes direct text and direct array inputs, not alias expansion,
    tuple contents, arbitrary wrappers, nested closures or closure returns.
    The arrow after the parameter list distinguishes closure and tuple aliases.
    """
    result = []
    pattern = r"\btypealias\s+(`[^`\r\n]+`|[^\W\d]\w*)\s*=\s*(?:@Sendable\s*)?(?=\()"
    for match in re.finditer(pattern, code):
        opening = match.end()
        closing = delimited_end(code, opening) - 1
        cursor = closing + 1
        while True:
            while cursor < len(code) and code[cursor].isspace():
                cursor += 1
            effect = re.match(r"(?:async|throws)\b", code[cursor:])
            if effect is None:
                break
            cursor += effect.end()
            while cursor < len(code) and code[cursor].isspace():
                cursor += 1
            if code[cursor:cursor + 1] == "(":
                cursor = delimited_end(code, cursor)
        if not code.startswith("->", cursor):
            continue
        # Split only the outer parameter slots. Nested carriers remain whole
        # and fail the direct-type match rather than leaking their String leaf.
        spans = typealias_outer_element_spans(code, opening, closing)
        for index, (begin, end) in enumerate(spans):
            while begin < end and code[begin].isspace():
                begin += 1
            while end > begin and code[end - 1].isspace():
                end -= 1
            if not DIRECT_TEXT_TYPE.fullmatch(code[begin:end]):
                continue
            line = bisect.bisect_left(newlines, begin)
            result.append(make_item(
                path, f"typealias-closure-parameter:{begin}",
                "TYPEALIAS_CLOSURE_TEXT_PARAMETER_DECLARATION", text[begin:end],
                line=line, column=begin - newlines[line - 1],
                typealiasSymbol=match[1], parameterIndex=index,
                classification=None, disposition="SEMANTIC_REVIEW_REQUIRED",
                ownershipEvidence="Closure-alias input has no independent producer/consumer ownership proof yet.",
                ownershipBoundary="An explicit closure-alias text input carries a value independently of the alias name, surrounding implementation and closure result. Trace its producer and consumer before classification."))
    return result


