INLINE_CLOSURE_KINDS = {"INLINE_CLOSURE_TEXT_PARAMETER_DECLARATION", "INLINE_CLOSURE_TEXT_RETURN_DECLARATION"}
INLINE_CLOSURE_TUPLE_KIND = "INLINE_CLOSURE_TUPLE_TEXT_ELEMENT_DECLARATION"
INLINE_CLOSURE_ATTRIBUTES = r"(?:@(?:escaping|autoclosure|Sendable|MainActor)\b\s*)*"


def inline_closure_annotation_items(path, text, code, newlines, begin, end, *, tuple_results=False, **parent):
    """Census direct outer closure slots; nested carriers retain their boundary."""
    result = []
    while True:
        while begin < end and code[begin].isspace():
            begin += 1
        while end > begin and code[end - 1].isspace():
            end -= 1
        begin += re.match(INLINE_CLOSURE_ATTRIBUTES, code[begin:end]).end()
        if code[begin:begin + 1] != "(" or begin >= end:
            return result
        closing = delimited_end(code, begin) - 1
        if closing >= end:
            return result
        cursor = closing + 1
        while True:
            while cursor < end and code[cursor].isspace():
                cursor += 1
            effect = re.match(r"(?:async|throws|rethrows)\b", code[cursor:end])
            if effect is None:
                break
            cursor += effect.end()
            while cursor < end and code[cursor].isspace():
                cursor += 1
            if code[cursor:cursor + 1] == "(":
                cursor = delimited_end(code, cursor)
        if code.startswith("->", cursor):
            break
        if code[closing + 1:end].strip() not in {"", "?", "!"}:
            return result
        # Parentheses around an optional whole closure do not make its input
        # tuple a nested closure. A plain tuple eventually has no arrow.
        begin, end = begin + 1, closing

    if tuple_results:
        returned = cursor + 2
        while returned < end and code[returned].isspace():
            returned += 1
        if code[returned:returned + 1] != "(":
            return result
        tuple_close = delimited_end(code, returned) - 1
        if tuple_close >= end or code[tuple_close + 1:end].strip() not in {"", "?", "!"}:
            return result
        spans = typealias_outer_element_spans(code, returned, tuple_close)
        if len(spans) < 2:
            return result
        for index, (start, stop) in enumerate(spans):
            while start < stop and code[start].isspace():
                start += 1
            label = re.match(r"(`[^`\r\n]+`|[^\W\d]\w*)\s*:\s*", code[start:stop])
            if label:
                start += label.end()
            while stop > start and code[stop - 1].isspace():
                stop -= 1
            if not DIRECT_TEXT_TYPE.fullmatch(code[start:stop]):
                continue
            line = bisect.bisect_left(newlines, start)
            result.append(make_item(
                path, f"inline-closure-tuple-element:{start}", INLINE_CLOSURE_TUPLE_KIND,
                text[start:stop], line=line, column=start - newlines[line - 1],
                elementIndex=index, **({"elementLabel": label[1]} if label else {}), **parent,
                classification=None, disposition="SEMANTIC_REVIEW_REQUIRED",
                ownershipEvidence="Closure tuple result element has no independent producer/consumer ownership proof yet.",
                ownershipBoundary="Each direct tuple result element has independent ownership; the enclosing callback, input slots and neighboring result values grant no translation permission."))
        return result

    def emit(role, start, stop, **fields):
        line = bisect.bisect_left(newlines, start)
        result.append(make_item(
            path, f"inline-closure-{role}:{start}",
            "INLINE_CLOSURE_TEXT_PARAMETER_DECLARATION" if role == "parameter" else "INLINE_CLOSURE_TEXT_RETURN_DECLARATION",
            text[start:stop], line=line, column=start - newlines[line - 1],
            classification=None, disposition="SEMANTIC_REVIEW_REQUIRED",
            ownershipEvidence="Inline closure text has no independent producer/consumer ownership proof yet.",
            ownershipBoundary="The closure's input and result values have independent ownership. Neither the enclosing function/storage declaration nor another closure slot establishes permission to translate this value.",
            **parent, **fields))

    for index, (start, stop) in enumerate(typealias_outer_element_spans(code, begin, closing)):
        while start < stop and code[start].isspace():
            start += 1
        while stop > start and code[stop - 1].isspace():
            stop -= 1
        label = re.match(r"(`?\w+`?)(?:\s+(`?\w+`?))?\s*:\s*", code[start:stop])
        if label:
            start += label.end()
        modifiers = re.match(r"(?:(?:inout|borrowing|consuming|sending|isolated)\s+)*", code[start:stop])
        start += modifiers.end()
        if DIRECT_TEXT_TYPE.fullmatch(code[start:stop]):
            emit("parameter", start, stop, closureParameterIndex=index,
                 **({"closureParameterSymbol": label[2] or label[1],
                     "closureParameterExternalLabel": label[1]} if label else {}))
    returned = cursor + 2
    while returned < end and code[returned].isspace():
        returned += 1
    if DIRECT_TEXT_TYPE.fullmatch(code[returned:end]):
        emit("return", returned, end)
    return result


def classify_reviewed_closure_tuple_results(path, text, items):
    if path != "FieldEvidenceApp/Infrastructure/Persistence/StoreGenerationFactory.swift":
        return
    expected = "93dfd727a19e8e44d0529a41f630a71dee579ce1a54bdb80c35f0031ca976d97"
    digest = "d6557d9481da8ef5b0e267bdd50de50498464725a2b449e2dd80aca1e13a4f3e"
    selected = [i for i in items if i["kind"] == INLINE_CLOSURE_TUPLE_KIND]
    if sha(text.encode()) != expected:
        raise ValueError("Reviewed callback tuple source changed: " + path)
    if len(selected) != 2 or sha(canonical(sorted(
            (i["kind"], i["locator"], i["sourceTextSHA256"]) for i in selected))) != digest:
        raise ValueError("Reviewed callback tuple record set changed: " + path)
    for item in selected:
        if item["classification"] is not None or item["disposition"] != "SEMANTIC_REVIEW_REQUIRED":
            raise ValueError("Callback tuple already has independent ownership: " + path)
        item.update(classification="MACHINE_IDENTIFIER", disposition="PRESERVE_MACHINE_VALUE",
                    ownershipEvidence="RELIABILITY_EXPORT_SORT_KEY: semanticExportV40's nested ordered helper has seven local callers. Every key closure returns workspaceID.rawValue.uuidString, eventID.uuidString and revision. These two String elements identify the workspace and event for deterministic export ordering; they do not carry incident wording or other record content.",
                    reviewedRecordSetSHA256=digest,
                    semanticReview={"sourceSHA256": expected, "rule": "RELIABILITY_EXPORT_SORT_KEY"})


def storage_closure_text_declarations(path, text, code, newlines, *, tuple_results=False):
    """Record explicit closure annotations on simple let/var declarations."""
    result = []
    pattern = r"\b(?:let|var)\s+(`[^`\r\n]+`|[^\W\d]\w*)\s*:\s*"
    for match in re.finditer(pattern, code):
        begin = match.end()
        probe = begin + re.match(INLINE_CLOSURE_ATTRIBUTES, code[begin:]).end()
        if code[probe:probe + 1] != "(":
            continue
        cursor, angle_depth = begin, 0
        while cursor < len(code):
            char = code[cursor]
            if char in "([":
                cursor = delimited_end(code, cursor)
                continue
            if char == "<":
                angle_depth += 1
            elif char == ">" and code[cursor - 1] != "-":
                angle_depth -= 1
            if angle_depth == 0:
                if char in "=;{},":
                    break
                if char == "\n":
                    prefix, following = code[begin:cursor].rstrip(), code[cursor + 1:].lstrip()
                    if not (prefix.endswith(("->", "."))
                            or re.fullmatch(INLINE_CLOSURE_ATTRIBUTES, prefix)
                            or re.match(r"(?:->|[?!.&]|(?:async|throws|rethrows)\b)", following)):
                        break
            cursor += 1
        result.extend(inline_closure_annotation_items(
            path, text, code, newlines, begin, cursor, tuple_results=tuple_results,
            closureParentKind="STORAGE_DECLARATION", parentStorageSymbol=match[1]))
    return result


