def bind_customer_learning_flow(path, text, code, items):
    spec = customer_learning_flow_spec()
    if path != spec["path"]:
        return
    if sha(text.encode()) != spec["sourceSHA256"]:
        raise ValueError("Customer learning validator source changed")
    calls = call_arguments(code, {"text"})
    if [(call["start"], call["end"]) for call in calls] != [fact[:2] for fact in spec["calls"]]:
        raise ValueError("Customer learning validator caller set changed")
    references = list(re.finditer(r"CustomerLearningValidationV1\s*\.\s*(text)\b", code))
    if [match.start(1) for match in references] != [fact[0] for fact in spec["calls"]]:
        raise ValueError("Customer learning validator has an unbound reference")
    for call, (_, _, _, symbol, _) in zip(calls, spec["calls"]):
        arguments = [text[start:end].strip() for start, end in call["arguments"]]
        expected = [symbol] + (["maximumBytes: 240"] if symbol in {"ownerReadableName", "processorName"} else [])
        if arguments != expected:
            raise ValueError("Customer learning validator input binding changed")
    by_locator = {item["locator"]: item for item in items}
    parent = by_locator[spec["parent"]]
    if parent["classification"] is not None or parent["disposition"] != "SEMANTIC_REVIEW_REQUIRED":
        raise ValueError("Customer learning validator boundary was already classified")
    bindings = customer_learning_call_bindings(spec, by_locator)
    producer_ids = [binding["producerItemID"] for binding in bindings]
    parent.update(classification=None, disposition=VARIANT_DISPOSITION,
                  ownershipEvidence=spec["evidence"], preserveCanonicalSource=True,
                  sourceBoundVariants=producer_ids, sourceBoundRuleID=spec["ruleID"],
                  sourceBoundCallBindings=bindings,
                  variantSetSHA256=variant_binding(spec, parent["id"], producer_ids),
                  semanticReview={"sourceSHA256": spec["sourceSHA256"], "rule": spec["ruleID"]})
    validate_customer_learning_flow({"path": path, "sha256": sha(text.encode()), "items": items})


def validate_customer_learning_flow(source):
    spec = customer_learning_flow_spec()
    if source["path"] != spec["path"] or source["sha256"] != spec["sourceSHA256"]:
        raise ValueError("Customer learning flow lacks its exact reviewed source")
    boundaries = [item for item in source["items"] if item["disposition"] == VARIANT_DISPOSITION or
                  any(key in item for key in ("sourceBoundVariants", "sourceBoundRuleID", "variantSetSHA256", "sourceBoundCallBindings"))]
    if len(boundaries) != 1 or boundaries[0]["locator"] != spec["parent"]:
        raise ValueError("Customer learning flow boundary is missing or substituted")
    if any(item["kind"] == "TEXT_HELPER_VALUE_ARGUMENT" for item in source["items"]):
        raise ValueError("Customer learning flow cannot adopt recipient argument records")
    by_locator = {item["locator"]: item for item in source["items"]}
    for _, _, offset, symbol, policy in spec["calls"]:
        item = by_locator.get(f"declaration:{offset}", {})
        classification, disposition, rule = spec["policies"][policy]
        if (item.get("kind"), item.get("symbol"), item.get("sourceTextSHA256"), item.get("owner"),
                item.get("classification"), item.get("disposition"), item.get("preserveCanonicalSource")) != (
                "DYNAMIC_TEXT_DECLARATION", symbol, sha(f"let {symbol}: String".encode()), "DOMAIN_CONTRACT_OWNER",
                classification, disposition, True):
            raise ValueError("Customer learning flow producer ownership changed")
        if item.get("semanticReview") != {"sourceSHA256": spec["sourceSHA256"], "rule": rule}:
            raise ValueError("Customer learning flow producer review changed")
    parent = boundaries[0]
    bindings = customer_learning_call_bindings(spec, by_locator)
    producer_ids = [binding["producerItemID"] for binding in bindings]
    if (parent.get("kind"), parent.get("sourceTextSHA256"), parent.get("owner"), parent.get("functionSymbol"),
            parent.get("symbol"), parent.get("parameterIndex"), parent.get("classification"), parent.get("disposition")) != (
            "FUNCTION_TEXT_PARAMETER_DECLARATION", sha(b"String"), "DOMAIN_CONTRACT_OWNER", "text",
            "value", 0, None, VARIANT_DISPOSITION):
        raise ValueError("Customer learning flow parent changed")
    if (parent.get("sourceBoundRuleID") != spec["ruleID"] or parent.get("sourceBoundVariants") != producer_ids or
            parent.get("sourceBoundCallBindings") != bindings or
            parent.get("variantSetSHA256") != variant_binding(spec, parent["id"], producer_ids) or
            parent.get("preserveCanonicalSource") is not True or "sourceItemID" in parent or
            parent.get("ownershipEvidence") != spec["evidence"] or
            parent.get("semanticReview") != {"sourceSHA256": spec["sourceSHA256"], "rule": spec["ruleID"]}):
        raise ValueError("Customer learning flow variants or caller evidence changed")


