def validate_illuminated_playbook_flow(source):
    spec = illuminated_playbook_flow_spec()
    if source["path"] != spec["path"] or source["sha256"] != spec["sourceSHA256"]:
        raise ValueError("Playbook return lacks its exact reviewed source")
    boundaries = [i for i in source["items"] if i["disposition"] == VARIANT_DISPOSITION or
                  any(key in i for key in ("sourceBoundVariants", "sourceBoundRuleID", "variantSetSHA256", "sourceBoundCallBindings"))]
    if len(boundaries) != 1 or boundaries[0]["locator"] != spec["parent"]:
        raise ValueError("Playbook return boundary is missing or substituted")
