    facts, producer_ids = [], []
    for case, locator in spec["branches"]:
        item = by_locator.get(locator, {})
        facts.append([case, locator, *[item.get(key) for key in
                     ("kind", "sourceTextSHA256", "classification", "disposition", "owner")]])
        producer_ids.append(item.get("id"))
    if sha(canonical(facts)) != spec["producerRecordSetSHA256"]:
        raise ValueError("Playbook return producer ownership changed")
    parent = boundaries[0]
    if (parent.get("kind"), parent.get("sourceTextSHA256"), parent.get("owner"),
            parent.get("functionSymbol"), parent.get("classification"), parent.get("disposition")) != (
            "FUNCTION_TEXT_RETURN_DECLARATION", sha(b"String"), spec["owner"], "english", None, VARIANT_DISPOSITION):
        raise ValueError("Playbook return has an unsupported scalar classification or source")
    if (parent.get("sourceBoundRuleID") != spec["ruleID"] or parent.get("sourceBoundVariants") != producer_ids
            or parent.get("variantSetSHA256") != variant_binding(spec, parent["id"], producer_ids)
            or parent.get("ownershipEvidence") != spec["evidence"]
            or parent.get("semanticReview") != {"sourceSHA256": spec["sourceSHA256"], "rule": spec["ruleID"]}
            or any(key in parent for key in ("sourceItemID", "parentLiteralID", "sourceBoundCallBindings",
                                             "preserveCanonicalSource", "parameterIndex", "symbol", "externalLabel"))):
        raise ValueError("Playbook return variants or authority boundaries changed")


