    spec = illuminated_playbook_flow_spec()
    if path != spec["path"]:
        return
    if sha(text.encode()) != spec["sourceSHA256"]:
        raise ValueError("Playbook return source changed")
    by_locator = {i["locator"]: i for i in items}
    parent = by_locator.get(spec["parent"])
    if parent is None or parent["classification"] is not None or parent["disposition"] != "SEMANTIC_REVIEW_REQUIRED":
        raise ValueError("Playbook return is missing or already classified")
    producer_ids = [by_locator[locator]["id"] for _, locator in spec["branches"]]
    parent.update(classification=None, disposition=VARIANT_DISPOSITION,
                  sourceBoundVariants=producer_ids, sourceBoundRuleID=spec["ruleID"],
                  variantSetSHA256=variant_binding(spec, parent["id"], producer_ids),
                  ownershipEvidence=spec["evidence"],
                  semanticReview={"sourceSHA256": spec["sourceSHA256"], "rule": spec["ruleID"]})
