def validate_mixed_flows(source):
    if source["path"] == illuminated_playbook_flow_spec()["path"]:
        validate_illuminated_playbook_flow(source)
        return
    if source["path"] == customer_learning_flow_spec()["path"]:
        validate_customer_learning_flow(source)
    else:
        if any("sourceBoundCallBindings" in item for item in source["items"]):
            raise ValueError("Unreviewed source-bound caller evidence")
        validate_recipient_flow(source)


def omit_unlabeled_progress_indicators(text, code, calls, items):
    """An argument-free spinner is not a text sink; its modifiers still are.

    Apply after the exact lexical-candidate reviews so their source/record pins
    remain valid. This removes nontext candidates, never changes ownership of
    a label, and deliberately leaves argument-taking overloads for review.
    """
    omitted = set()
    for call in calls:
        if call["name"] != "ProgressView":
            continue
        opening = code.index("(", call["start"], call["end"])
        argument_text = text[opening + 1:call["end"] - 1]
        # A string literal is masked to whitespace in code, including "".
        # Remove only comments from the raw argument text, retaining strings.
        trivia_free = list(argument_text)
        for span in SwiftLexer(argument_text).scan():
            if span["kind"] == "SWIFT_COMMENT":
                trivia_free[span["start"]:span["end"]] = " " * (span["end"] - span["start"])
        if "".join(trivia_free).strip():
            continue
        # A trailing label closure remains a presentation candidate; its
        # nested Text calls and literals are also independently inventoried.
        if code[call["end"]:].lstrip().startswith("{"):
            continue
        omitted.add(f'call:{call["start"]}:{call["end"]}')
    removed_ids = {item["id"] for item in items
                   if item["kind"] == "TEXT_PRESENTATION_CALL" and item["locator"] in omitted}
    if any(item.get(key) in removed_ids for item in items
           for key in ("parentPresentationID", "sourceItemID")):
        raise ValueError("Unlabeled progress indicator unexpectedly owns a text binding")
    return [item for item in items if item["id"] not in removed_ids]


def swift_items(path, text):
    lexer = SwiftLexer(text)
    spans = lexer.scan()
    newlines = [-1] + [m.start() for m in re.finditer("\n", text)]
    items = []
    for span in spans:
        start, end, kind = span["start"], span["end"], span["kind"]
        line = bisect.bisect_left(newlines, start)
        previous = text[max(0, start - 280):start]
        literal = make_item(path, f"chars:{start}:{end}", kind, text[start:end],
                               previous, line=line, column=start - newlines[line - 1],
                               rawHashes=span.get("rawHashes"), multiline=span.get("multiline"),
                               interpolationSpans=span.get("interpolations", []))
        items.append(literal)
        for begin, stop in span.get("interpolations", []):
            expression_start, expression_end = begin + 2 + span["rawHashes"], stop - 1
            expression_line = bisect.bisect_left(newlines, expression_start)
            items.append(make_item(path, f"interpolation:{expression_start}:{expression_end}",
                                   "STRING_INTERPOLATION_VALUE", text[expression_start:expression_end],
                                   line=expression_line, column=expression_start - newlines[expression_line - 1],
                                   parentLiteralID=literal["id"],
                                   ownershipBoundary="The surrounding template's ownership does not establish ownership or translation permission for this inserted value."))
    # Mask lexical spans before examining declarations and display sinks. This
    # prevents false declarations/calls from comments and literal payloads.
    code = masked_swift(text, spans)
    for match in TEXT_DECLARATION.finditer(code):
        line = bisect.bisect_left(newlines, match.start())
        items.append(make_item(path, f"declaration:{match.start()}", "DYNAMIC_TEXT_DECLARATION",
                               text[match.start():match.end()], line=line, symbol=match[1]))
    local_ui_helpers = {"sectionHeading", "valueRow"} if path in {
        "FieldEvidenceApp/Features/VoiceCapture/VoicePushToTalkCaptureView.swift",
        "FieldEvidenceApp/Features/PartsStock/PartsStockWorkflowView.swift"} else set()
    if path == "FieldEvidenceApp/Features/Scheduling/AdvancedRecurrenceWorkflowView.swift":
        local_ui_helpers = {"sectionHeading", "summaryRow", "commandButton"}
    if path == "FieldEvidenceApp/Features/CheckRunner/EvidenceCurationView.swift":
        local_ui_helpers = {"sectionHeading", "markupButton", "WorklightStatusBadge"}
    if path == "FieldEvidenceApp/Features/Reports/ReportsRootView.swift":
        local_ui_helpers = {"ReportVisitFact", "ReportHistoryUnavailableView", "WorklightStatusBadge", "comparisonHeading", "headingText"}
    if path == "FieldEvidenceApp/Features/Activities/PunchReviewWorkflowView.swift":
        local_ui_helpers = {"sectionHeading", "commandButton", "stateLabel", "capabilityRow"}
    if path == "FieldEvidenceApp/Features/Activities/InstallationWorkflowView.swift":
        local_ui_helpers = {"sectionHeading", "commandButton", "stateLabel", "capabilityRow"}
    if path == "FieldEvidenceApp/Features/Integrations/IncumbentFileAdapterWorkflowView.swift":
        local_ui_helpers = {"sectionHeading", "commandButton", "valueRow"}
    if path == "FieldEvidenceApp/Features/Recovery/RecoveryCenterView.swift":
        local_ui_helpers = {"actionRow"}
    if path == "FieldEvidenceApp/Features/CheckRunner/OutcomeReviewView.swift":
        local_ui_helpers = {"choiceButton", "reviewRow", "reviewEvidence", "WorklightStatusBadge"}
    if path == "FieldEvidenceApp/Features/MyDay/MyDayWorkflowView.swift":
        local_ui_helpers = {"sectionHeading", "valueRow"}
    if path == "FieldEvidenceApp/Features/ReviewExchange/RecipientReviewWorkflowView.swift":
        local_ui_helpers = {"sectionHeading", "commandButton", "stateRow"}
    if path == "FieldEvidenceApp/Features/WorkResources/ManualWorkResourceWorkflowView.swift":
        local_ui_helpers = {"sectionHeading", "commandButton", "valueRow", "materials"}
    ui_calls = call_arguments(code, UI_CALLS | local_ui_helpers)
    for call in ui_calls:
        if path in {"FieldEvidenceApp/Features/Integrations/IncumbentFileAdapterWorkflowView.swift",
                    "FieldEvidenceApp/Features/MyDay/MyDayWorkflowView.swift"} and call["name"] == "valueRow":
            # This helper presents both label and value; owning its literal
            # label alone cannot establish ownership of the complete call.
            call["requiresMixedArgumentReview"] = True
        if (path == "FieldEvidenceApp/Features/ReviewExchange/RecipientReviewWorkflowView.swift" and call["name"] == "stateRow") or (
                path == "FieldEvidenceApp/Features/WorkResources/ManualWorkResourceWorkflowView.swift" and call["name"] in {"valueRow", "materials"}):
            call["requiresMixedArgumentReview"] = True
        begin, end = call["start"], call["end"]
        line = bisect.bisect_left(newlines, begin)
        sink = make_item(path, f"call:{begin}:{end}", "TEXT_PRESENTATION_CALL",
                         text[begin:end], line=line, symbol=call["name"])
        items.append(sink)
        if call["name"] in {"TextField", "SecureField", "TextEditor"}:
            for index, (arg_begin, arg_end) in enumerate(call["arguments"]):
                label = re.match(r"\s*text\s*:", code[arg_begin:arg_end])
                if label is None:
                    continue
                value_begin = arg_begin + label.end()
                while value_begin < arg_end and text[value_begin].isspace():
                    value_begin += 1
                value_end = arg_end
                while value_end > value_begin and text[value_end - 1].isspace():
                    value_end -= 1
                value_line = bisect.bisect_left(newlines, value_begin)
                items.append(make_item(path, f"input:{value_begin}:{value_end}", "TEXT_INPUT_BINDING",
                                       text[value_begin:value_end], line=value_line,
                                       symbol=call["name"], parentPresentationID=sink["id"],
                                       consumerArgumentIndex=index, consumerArgumentLabel="text",
                                       ownershipBoundary="An editable value has independent provenance from the control label; binding syntax alone does not distinguish authored text, canonical identifiers, formatted values or constant app copy."))
    classify_reviewed_swift(path, text, code, items)
    link_literal_presentations(text, items, ui_calls)
    items.extend(function_text_declarations(path, text, code, newlines))
    items.extend(function_text_declarations(path, text, code, newlines, initializers=True))
    items.extend(function_text_declarations(path, text, code, newlines, special_kind="SUBSCRIPT"))
    items.extend(function_text_declarations(path, text, code, newlines, special_kind="OPERATOR"))
    bind_recipient_flow(path, text, code, items, newlines)
    classify_reviewed_c52_contact_tokens(path, text, items)
    classify_reviewed_special_callable_text(path, text, items)
    # New composite carriers must not inherit earlier scalar/array ownership.
    items.extend(function_text_declarations(path, text, code, newlines, dictionaries=True))
    items.extend(function_text_declarations(path, text, code, newlines, initializers=True, dictionaries=True))
    items.extend(function_text_declarations(path, text, code, newlines, special_kind="SUBSCRIPT", dictionaries=True))
    items.extend(function_text_declarations(path, text, code, newlines, special_kind="OPERATOR", dictionaries=True))
    classify_reviewed_dictionary_text(path, text, items)
    # Run after every existing review: newly found carriers need their own proof.
    items.extend(function_text_declarations(path, text, code, newlines, collections=True))
    items.extend(function_text_declarations(path, text, code, newlines, initializers=True, collections=True))
    items.extend(function_text_declarations(path, text, code, newlines, special_kind="SUBSCRIPT", collections=True))
    items.extend(function_text_declarations(path, text, code, newlines, special_kind="OPERATOR", collections=True))
    classify_reviewed_collection_text(path, text, items)
    classify_reviewed_catalog_adapters(path, text, items)
    classify_reviewed_workflow_remainders(path, text, items)
    bind_customer_learning_flow(path, text, code, items)
    bind_illuminated_playbook_flow(path, text, items)
    # Preserve historical record sets and require fresh ownership for aliases.
    items.extend(typealias_closure_text_declarations(path, text, code, newlines))
    classify_reviewed_closure_alias_text(path, text, items)
    items.extend(typealias_tuple_text_declarations(path, text, code, newlines))
    classify_reviewed_tuple_alias_text(path, text, items)
    # Inline closure carriers are a separate census partition, after all old
    # semantic reviews and their immutable source/record-set guards.
    items.extend(function_text_declarations(path, text, code, newlines, closures=True))
    items.extend(function_text_declarations(path, text, code, newlines, initializers=True, closures=True))
    items.extend(function_text_declarations(path, text, code, newlines, special_kind="SUBSCRIPT", closures=True))
    items.extend(function_text_declarations(path, text, code, newlines, special_kind="OPERATOR", closures=True))
    items.extend(storage_closure_text_declarations(path, text, code, newlines))
    classify_reviewed_inline_closure_text(path, text, items)
    # Tuple results have their own ownership partition, after existing reviews.
    items.extend(function_text_declarations(path, text, code, newlines, tuple_returns=True))
    items.extend(function_text_declarations(path, text, code, newlines, special_kind="SUBSCRIPT", tuple_returns=True))
    items.extend(function_text_declarations(path, text, code, newlines, special_kind="OPERATOR", tuple_returns=True))
    classify_reviewed_function_tuple_results(path, text, items)
    # Callback tuple elements are independent of all prior closure/tuple reviews.
    items.extend(function_text_declarations(path, text, code, newlines, closure_tuples=True))
    items.extend(function_text_declarations(path, text, code, newlines, initializers=True, closure_tuples=True))
    items.extend(function_text_declarations(path, text, code, newlines, special_kind="SUBSCRIPT", closure_tuples=True))
    items.extend(function_text_declarations(path, text, code, newlines, special_kind="OPERATOR", closure_tuples=True))
    items.extend(storage_closure_text_declarations(path, text, code, newlines, tuple_results=True))
    classify_reviewed_closure_tuple_results(path, text, items)
    return omit_unlabeled_progress_indicators(text, code, ui_calls, items)


def link_literal_presentations(text, items, calls):
    """Own only a proven literal label argument, not every value in a control."""
    literal_by_span = {tuple(map(int, item["locator"].split(":")[1:])): item
                       for item in items if item["kind"] == "SWIFT_STRING"}
    sinks = {item["locator"]: item for item in items if item["kind"] == "TEXT_PRESENTATION_CALL"}
    for call in calls:
        sink = sinks[f'call:{call["start"]}:{call["end"]}']
        if sink["classification"] is not None or not call["arguments"] or call.get("requiresMixedArgumentReview"):
            continue
        begin, end = call["arguments"][0]
        while begin < end and text[begin].isspace():
            begin += 1
        while end > begin and text[end - 1].isspace():
            end -= 1
        literal = literal_by_span.get((begin, end))
        if literal is None or literal["classification"] is None:
            continue
        classification, disposition = literal["classification"], literal["disposition"]
        key = text[begin:end]
        if classification == "MACHINE_IDENTIFIER" and key.startswith('"') and key.endswith('"') and key[1:-1] in CATALOG_KEYS:
            # Literal SwiftUI localization lookup: the key stays machine-owned;
            # this source occurrence is its app/a11y presentation sink.
            classification = "ACCESSIBILITY_TEXT" if call["name"].startswith("accessibility") else "APP_OWNED_USER_FACING_COPY"
            disposition = "LOCALIZE_STABLE_KEY"
            sink["catalogKey"] = key[1:-1]
        sink.update(classification=classification, disposition=disposition,
                    sourceItemID=literal["id"], consumerArgumentIndex=0,
                    ownershipEvidence="LITERAL_LABEL_PRESENTATION: first unlabeled argument is this exact inventoried literal; inserted values and other control arguments retain separate ownership.")


def pointer_escape(text):
    return text.replace("~", "~0").replace("/", "~1")


def structured_items(path, value, pointer="", plist=False):
    result = []
    if isinstance(value, dict):
        for key, child in value.items():
            location = pointer + "/" + pointer_escape(str(key))
            result.append(make_item(path, location + "/@key", "PLIST_KEY" if plist else "JSON_KEY", str(key)))
            result.extend(structured_items(path, child, location, plist))
    elif isinstance(value, list):
        for index, child in enumerate(value):
            result.extend(structured_items(path, child, pointer + "/" + str(index), plist))
    elif isinstance(value, str):
        result.append(make_item(path, pointer, "PLIST_STRING" if plist else "JSON_STRING", value))
    return result


def file_items(path, raw):
    if path == ".codex/config.toml":
        return [], "OWNER_CONFIGURATION_EXCLUDED", "Owner configuration is outside product text; contents are not copied."
    try:
        text = raw.decode("utf-8-sig")
    except UnicodeDecodeError:
        return [], "BINARY_RESOURCE", "Hash-bound binary; no text decoding or OCR claim."
    if path.endswith(".swift"):
        return swift_items(path, text), "SWIFT_LEXICAL_AND_DYNAMIC_SURFACES", None
    if path.startswith(("FieldEvidenceApp/", "FieldEvidenceAppTests/", "FieldEvidenceAppUITests/",
                        "TestFixtures/", "TestSupport/", "TestPlans/", "Release/", "docs/product/")):
        if path.endswith((".json", ".xcstrings", ".storekit", ".xctestplan")):
            return reviewed_resource_items(path, raw, structured_items(path, json.loads(text))), "STRUCTURED_STRING_KEYS_AND_VALUES", None
        if path.endswith((".plist", ".xcprivacy", ".entitlements")):
            return reviewed_resource_items(path, raw, structured_items(path, plistlib.loads(raw), plist=True)), "PLIST_STRING_KEYS_AND_VALUES", None
        if path.startswith(("Release/", "docs/product/")):
            lines = [make_item(path, f"line:{n}", "METADATA_DOCUMENT_LINE", line, line=n)
                     for n, line in enumerate(text.splitlines(), 1) if line.strip()]
            return lines, "RELEASE_OR_PRODUCT_DOCUMENT_LINES", None
    if path.endswith(".pbxproj"):
        lines = [make_item(path, f"line:{n}", "PROJECT_CONFIGURATION", line, line=n)
                 for n, line in enumerate(text.splitlines(), 1) if line.strip()]
        return lines, "PROJECT_CONFIGURATION_LINES", None
    return [make_item(path, "document", "DEVELOPER_DOCUMENT", text)], "DEVELOPER_DOCUMENT", None


def build_inventory():
    tree = source_tree()
    blobs = source_blobs(tree)
    CATALOG_KEYS.clear()
    for path in ["FieldEvidenceApp/Resources/Localizable.xcstrings", "FieldEvidenceApp/InfoPlist.xcstrings"]:
        CATALOG_KEYS.update(json.loads(blobs[path])["strings"])
    files = []
    for path, mode, oid in tree:
        raw = blobs[path]
        try:
            items, route, limitation = file_items(path, raw)
        except ValueError as error:
            raise ValueError(f"{path}: {error}") from error
        files.append({"path": path, "blobOID": oid, "sha256": sha(raw), "bytes": len(raw),
                      "mode": mode, "owner": role_for(path), "coverageRoute": route,
                      "limitation": limitation, "items": items})
    unresolved = sum(i["disposition"] == "SEMANTIC_REVIEW_REQUIRED" for f in files for i in f["items"])
    return seal({
        "schema": "V30TextBearingSurfaceInventoryV1", "cardID": CARD,
        "status": "DRAFT_REQUIRES_SEMANTIC_REVIEW" if unresolved else "READY_FOR_STATIC_VALIDATION",
        "sourceHead": BASE, "sourceTree": git("rev-parse", BASE + "^{tree}").decode().strip(),
        "sourceUniverse": "Every tracked blob in the frozen isolated V30 tree; no other worktree or Phase10 ref.",
        "sourceSpanUnit": "Unicode code points in decoded source; one-based line/column. JSON pointers are RFC6901.",
        "dispositionSchemaPayloadDigest": schema_document()["payloadDigest"],
        "coverageLimitations": [
            "Lexical census is not native AST, runtime reachability or linguistic acceptance.",
            "Dynamic declarations and presentation calls require explicit producer/consumer ownership.",
            "Named func, subscript and operator parameters/returns, plus initializer parameters, with explicit String, Swift.String, LocalizedStringKey, SwiftUI.LocalizedStringKey or direct arrays thereof are inventoried separately, including optional/variadic forms. Operator recognition includes Swift Unicode heads, combining/variation-selector continuations and dot-leading forms; lexical capture does not establish native overload legality. A supplemental DICTIONARY pass captures text keys/values through nested bracket collections and standard Dictionary/Array/Optional wrappers, preserving each whole carrier for independent ownership review. It does not infer nominal leaf contents. Special callable inputs do not inherit stored-property classifications. Implicit accessor inputs, inferred types, typealiases, arbitrary generic wrappers, tuples and closure-carried text remain coverage-review obligations, including collections containing those unsupported composite types.",
            "A supplemental COLLECTION pass captures remaining explicit standard Array/Set/Optional wrappers and nested bracket arrays, including Set-containing dictionaries. Existing direct and DICTIONARY records retain their original partition and guards; every newly discovered carrier has independent ownership. Unsupported aliases, arbitrary generics, tuples and closures remain coverage obligations.",
            "A supplemental closure-typealias pass captures direct String/LocalizedStringKey and direct array parameter slots in nongeneric closure aliases, including optional and @Sendable forms and async/throws effects. These records have independent ownership. Alias expansion/use sites, other attributes, parameter modifiers, closure returns, nested closures, tuple contents and wrapped alias carriers remain coverage obligations.",
            "A supplemental tuple-typealias pass captures direct text and direct array elements of nongeneric tuple aliases, retaining each element index and any label independently. Parenthesized single types and closure aliases are excluded. Nested tuple/closure contents, arbitrary wrappers, alias use sites and non-alias tuple carriers still require coverage review.",
            "A supplemental inline-closure pass captures direct text/array input slots and direct text/array results of explicit closure annotations on function/initializer/subscript/operator parameters and simple let/var declarations. It recognizes escaping/autoclosure/Sendable/MainActor attributes, effects, labelled inputs and parentheses around optional closures. Each record retains its exact parent and inner slot independently. Nested tuple/generic/closure contents, alias use sites, additional attributes, function-returned closures, inferred closure types and multi-pattern storage declarations remain coverage obligations.",
            "A supplemental inline-closure tuple-result pass captures each direct text/direct-array element of a callback's outer tuple result, including optional tuple results and optional whole closures. It preserves the exact function/initializer/subscript/operator parameter or storage parent and each element index/label, independently of legacy closure input/result records. Nested tuple/closure elements, aliases and generic-wrapped elements remain coverage obligations; eligible direct siblings are retained.",
            "Each interpolation expression has its own ownership record; the template's classification never grants permission to translate inserted user, machine or system values.",
            "TextField, SecureField and TextEditor text bindings have separate value records; a localized prompt never establishes ownership of the editable value.",
            "Developer documents are inventoried as whole source-bound documents; runtime/release structured sources use individual string leaves and keys.",
            "Binary resources are hash-bound with no fabricated OCR/text extraction.",
            "System-provided display is an explicit non-app-owned exclusion from blueprint section10.3.",
            "Records count source occurrences, producer declarations and presentation sinks, not unique messages. A single-origin declaration can inherit its carried value's ownership; its source spelling is not localizable copy. Proven mixed carriers reference one shared set of independently classified source argument records. Open or unproved producer sets remain unresolved. Shared catalogKey/producer bindings must prevent double-counting during later normalization.",
        ],
        "developmentDiagnostics": [
            "Initial draft generation stopped on escaped quote spellings inside interpolation in V4BackupContracts.swift. No product bytes were changed.",
            "Scanner now retains those spellings as explicit SWIFT_ESCAPED_INTERPOLATION_TOKEN observations; this is not compiler acceptance.",
            "Speech recognition permission exists in Info.plist but has no corresponding InfoPlist.xcstrings entry at the frozen base; later catalog work must address the gap.",
            "Semantic review initially proposed a residual machine classification in LocalizationContractsV1; direct source inspection found returned recovery sentences. That proposal was not applied; positive factory rules replaced it and all remaining unknowns stay unresolved.",
            "Bundled pack review found exact loader parity and app-controlled content, not an administrator editing route. The inventory preserves canonical pack bytes while retaining app-owned presentation and separate professional-review dispositions.",
        ],
        "finalCredit": False, "nativeEvidence": "NOT_EXECUTED_NO_NATIVE_CREDIT",
        "files": files, "unresolvedOwnershipCount": unresolved,
    })


def schema_document():
    string = {"type": "string", "minLength": 1}
    hash256 = {"type": "string", "pattern": "^[a-f0-9]{64}$"}
    inline_function_fields = ["parentFunctionSymbol", "parentCallableKind", "parentParameterIndex", "parentParameterSymbol", "parentExternalLabel"]
    inline_context = {
        "required": ["closureParentKind", "ownershipBoundary", "line", "column"],
        "properties": {"ownershipBoundary": string, "line": {"type": "integer", "minimum": 1},
                       "column": {"type": "integer", "minimum": 1}},
        "oneOf": [
            {"required": inline_function_fields,
             "properties": {"closureParentKind": {"const": "FUNCTION_PARAMETER"},
                            "parentFunctionSymbol": string, "parentParameterSymbol": string, "parentExternalLabel": string,
                            "parentParameterIndex": {"type": "integer", "minimum": 0},
                            "parentCallableKind": {"enum": ["FUNCTION", "INITIALIZER", "SUBSCRIPT", "OPERATOR"]}},
             "not": {"required": ["parentStorageSymbol"]}},
            {"required": ["parentStorageSymbol"],
             "properties": {"closureParentKind": {"const": "STORAGE_DECLARATION"}, "parentStorageSymbol": string},
             "not": {"anyOf": [{"required": [field]} for field in inline_function_fields]}},
        ],
    }
    # Rule specs use Python tuples internally; emit JSON-native arrays so a
    # saved-and-reloaded contract compares equal to the generated contract.
    source_bound_rules = json.loads(canonical([recipient_flow_spec(), customer_learning_flow_spec(), illuminated_playbook_flow_spec()]))
    source_bound_rule_ids = [rule["ruleID"] for rule in source_bound_rules]
    item_fields = ["id", "locator", "kind", "recordRole", "sourceTextSHA256", "preview",
                   "owner", "classification", "disposition", "ownershipEvidence"]
    file_fields = ["path", "blobOID", "sha256", "bytes", "mode", "owner", "coverageRoute", "items"]
    return seal({
        "schema": "V30TextSurfaceDispositionSchemaV1", "cardID": CARD,
        "classificationVocabulary": CLASSES, "dispositionVocabulary": DISPOSITIONS,
        "requiredFileFields": file_fields,
        "requiredItemFields": item_fields,
        "allowedClassDispositions": CLASS_DISPOSITIONS,
        "recordRolesByKind": RECORD_ROLES,
        "sourceBoundCarrierRules": source_bound_rules,
        "jsonSchema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": "V30 source-bound text inventory (draft or structurally ready)",
            "type": "object",
            "required": ["schema", "cardID", "sourceHead", "sourceTree", "files", "status",
                         "payloadDigest", "dispositionSchemaPayloadDigest", "finalCredit", "nativeEvidence", "unresolvedOwnershipCount"],
            "properties": {
                "schema": {"const": "V30TextBearingSurfaceInventoryV1"}, "cardID": {"const": CARD},
                "sourceHead": {"const": BASE}, "sourceTree": {"type": "string", "pattern": "^[a-f0-9]{40}$"},
                "status": {"enum": ["DRAFT_REQUIRES_SEMANTIC_REVIEW", "READY_FOR_STATIC_VALIDATION"]},
                "payloadDigest": hash256, "dispositionSchemaPayloadDigest": hash256,
                "finalCredit": {"const": False}, "nativeEvidence": {"const": "NOT_EXECUTED_NO_NATIVE_CREDIT"},
                "unresolvedOwnershipCount": {"type": "integer", "minimum": 0},
                "files": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/sourceFile"}},
            },
            "$defs": {
                "sourceFile": {"type": "object", "required": file_fields, "properties": {
                    "path": string, "blobOID": {"type": "string", "pattern": "^[a-f0-9]{40}$"},
                    "sha256": hash256, "bytes": {"type": "integer", "minimum": 0},
                    "mode": {"enum": ["100644", "100755"]}, "owner": string, "coverageRoute": string,
                    "items": {"type": "array", "items": {"$ref": "#/$defs/textItem"}},
                }},
                "textItem": {"type": "object", "required": item_fields, "properties": {
                    "textTypeShape": {"enum": ["DICTIONARY", "COLLECTION"]},
                    "id": {"type": "string", "pattern": "^[a-f0-9]{24}$"}, "locator": string,
                    "kind": {"enum": list(RECORD_ROLES)}, "recordRole": {"enum": sorted(set(RECORD_ROLES.values()))},
                    "sourceTextSHA256": hash256, "preview": {"type": "string", "maxLength": 180},
                    "owner": string, "classification": {"enum": CLASSES + [None]},
                    "disposition": {"enum": DISPOSITIONS}, "ownershipEvidence": string,
                }, "allOf": [
                    {"if": {"properties": {"classification": {"const": key}}},
                     "then": {"properties": {"disposition": {"enum": values}}}}
                    for key, values in [(None, ["SEMANTIC_REVIEW_REQUIRED", VARIANT_DISPOSITION]), *CLASS_DISPOSITIONS.items()]
                ] + [{
                    "if": {"properties": {"disposition": {"const": VARIANT_DISPOSITION}}},
                    "then": {"required": ["sourceBoundRuleID", "sourceBoundVariants", "variantSetSHA256"],
                             "properties": {"classification": {"type": "null"},
                                            "kind": {"enum": ["FUNCTION_TEXT_PARAMETER_DECLARATION", "FUNCTION_TEXT_RETURN_DECLARATION", "TEXT_PRESENTATION_CALL"]},
                                            "sourceBoundRuleID": {"enum": source_bound_rule_ids},
                                            "sourceBoundVariants": {"type": "array", "minItems": 2, "uniqueItems": True,
                                                                    "items": {"type": "string", "pattern": "^[a-f0-9]{24}$"}},
                                            "variantSetSHA256": hash256}},
                }, {
                    "if": {"properties": {"kind": {"const": "TEXT_HELPER_VALUE_ARGUMENT"}}},
                    "then": {"required": ["parentPresentationID", "consumerArgumentIndex", "consumerArgumentLabel", "producerItemIDs"],
                             "properties": {"parentPresentationID": {"type": "string", "pattern": "^[a-f0-9]{24}$"},
                                            "consumerArgumentIndex": {"const": 1}, "consumerArgumentLabel": {"const": "value"},
                                            "producerItemIDs": {"type": "array", "uniqueItems": True,
                                                                "items": {"type": "string", "pattern": "^[a-f0-9]{24}$"}}}},
                }, {
                    "if": {"properties": {"kind": {"enum": ["FUNCTION_TEXT_PARAMETER_DECLARATION", "FUNCTION_TEXT_RETURN_DECLARATION"]}}},
                    "then": {"required": ["functionSymbol", "ownershipBoundary", "line", "column"],
                             "properties": {"functionSymbol": string, "ownershipBoundary": string,
                                            "line": {"type": "integer", "minimum": 1}, "column": {"type": "integer", "minimum": 1}}},
                }, {
                    "if": {"properties": {"kind": {"const": "TYPEALIAS_CLOSURE_TEXT_PARAMETER_DECLARATION"}}},
                    "then": {"required": ["typealiasSymbol", "parameterIndex", "ownershipBoundary", "line", "column"],
                             "properties": {"typealiasSymbol": string, "ownershipBoundary": string,
                                            "parameterIndex": {"type": "integer", "minimum": 0},
                                            "line": {"type": "integer", "minimum": 1}, "column": {"type": "integer", "minimum": 1}}},
                }, {
                    "if": {"properties": {"kind": {"const": "TYPEALIAS_TUPLE_TEXT_ELEMENT_DECLARATION"}}},
                    "then": {"required": ["typealiasSymbol", "elementIndex", "ownershipBoundary", "line", "column"],
                             "properties": {"typealiasSymbol": string, "ownershipBoundary": string, "elementLabel": string,
                                            "elementIndex": {"type": "integer", "minimum": 0},
                                            "line": {"type": "integer", "minimum": 1}, "column": {"type": "integer", "minimum": 1}}},
                }, {
                    "if": {"properties": {"kind": {"enum": sorted(INLINE_CLOSURE_KINDS | {INLINE_CLOSURE_TUPLE_KIND})}}},
                    "then": inline_context,
                }, {
                    "if": {"properties": {"kind": {"enum": sorted(INLINE_CLOSURE_KINDS)}}},
                    "then": {"not": {"anyOf": [{"required": [field]} for field in ["elementIndex", "elementLabel"]]}},
                }, {
                    "if": {"properties": {"kind": {"const": INLINE_CLOSURE_TUPLE_KIND}}},
                    "then": {"required": ["elementIndex"],
                             "properties": {"elementIndex": {"type": "integer", "minimum": 0}, "elementLabel": string},
                             "not": {"anyOf": [{"required": [field]} for field in
                                               ["closureParameterIndex", "closureParameterSymbol", "closureParameterExternalLabel",
                                                "functionSymbol", "callableKind", "typealiasSymbol", "parameterIndex", "symbol", "externalLabel"]]}},
                }, {
                    "if": {"properties": {"kind": {"const": "FUNCTION_TUPLE_TEXT_ELEMENT_DECLARATION"}}},
                    "then": {"required": ["functionSymbol", "callableKind", "elementIndex", "ownershipBoundary", "line", "column"],
                             "properties": {"functionSymbol": string, "ownershipBoundary": string, "elementLabel": string,
                                            "callableKind": {"enum": ["FUNCTION", "SUBSCRIPT", "OPERATOR"]},
                                            "elementIndex": {"type": "integer", "minimum": 0},
                                            "line": {"type": "integer", "minimum": 1}, "column": {"type": "integer", "minimum": 1}},
                             "not": {"anyOf": [{"required": [field]} for field in
                                               ["parameterIndex", "symbol", "externalLabel", "typealiasSymbol"]]}},
                }, {
                    "if": {"properties": {"kind": {"const": "INLINE_CLOSURE_TEXT_PARAMETER_DECLARATION"}}},
                    "then": {"required": ["closureParameterIndex"],
                             "properties": {"closureParameterIndex": {"type": "integer", "minimum": 0}},
                             "allOf": [{"if": {"anyOf": [{"required": ["closureParameterSymbol"]}, {"required": ["closureParameterExternalLabel"]}]},
                                         "then": {"required": ["closureParameterSymbol", "closureParameterExternalLabel"],
                                                  "properties": {"closureParameterSymbol": string, "closureParameterExternalLabel": string}}}]},
                }, {
                    "if": {"properties": {"kind": {"const": "INLINE_CLOSURE_TEXT_RETURN_DECLARATION"}}},
                    "then": {"not": {"anyOf": [{"required": [field]} for field in
                                                  ["closureParameterIndex", "closureParameterSymbol", "closureParameterExternalLabel"]]}},
                }, {
                    "if": {"properties": {"kind": {"const": "FUNCTION_TEXT_PARAMETER_DECLARATION"}}},
                    "then": {"required": ["symbol", "externalLabel", "parameterIndex"],
                             "properties": {"symbol": string, "externalLabel": string,
                                            "parameterIndex": {"type": "integer", "minimum": 0}}},
                }, {
                    "if": {"anyOf": [{"required": ["callableKind"]},
                                      {"required": ["functionSymbol"], "properties": {"functionSymbol": {"enum": ["init", "subscript"]}}}]},
                    "then": {"required": ["callableKind", "functionSymbol", "kind"],
                             "properties": {"kind": {"enum": ["FUNCTION_TEXT_PARAMETER_DECLARATION", "FUNCTION_TEXT_RETURN_DECLARATION", "FUNCTION_TUPLE_TEXT_ELEMENT_DECLARATION"]}},
                             "oneOf": [
                                 {"properties": {"callableKind": {"const": "FUNCTION"},
                                                 "functionSymbol": {"pattern": r"^(?:`[^`\r\n]+`|[^\W\d]\w*)$", "not": {"enum": ["init", "subscript"]}},
                                                 "kind": {"const": "FUNCTION_TUPLE_TEXT_ELEMENT_DECLARATION"}}},
                                 {"properties": {"callableKind": {"const": "INITIALIZER"}, "functionSymbol": {"const": "init"},
                                                 "kind": {"const": "FUNCTION_TEXT_PARAMETER_DECLARATION"}}},
                                 {"properties": {"callableKind": {"const": "SUBSCRIPT"}, "functionSymbol": {"const": "subscript"}}},
                                 {"properties": {"callableKind": {"const": "OPERATOR"}, "functionSymbol": {"pattern": "^" + SWIFT_OPERATOR_PATTERN + "$"}}},
                             ]},
                }, {
                    "if": {"required": ["textTypeShape"]},
                    "then": {"properties": {"kind": {"enum": ["FUNCTION_TEXT_PARAMETER_DECLARATION", "FUNCTION_TEXT_RETURN_DECLARATION"]}}},
                }, {
                    "if": {"properties": {"kind": {"const": "TEXT_INPUT_BINDING"}}},
                    "then": {"required": ["parentPresentationID", "consumerArgumentIndex", "consumerArgumentLabel", "symbol"],
                             "properties": {"parentPresentationID": {"type": "string", "pattern": "^[a-f0-9]{24}$"},
                                            "consumerArgumentIndex": {"type": "integer", "minimum": 0},
                                            "consumerArgumentLabel": {"const": "text"},
                                            "symbol": {"enum": ["TextField", "SecureField", "TextEditor"]}}},
                }, {
                    "if": {"properties": {"classification": {"const": "REPORT_EXPORT_CHROME"}, "disposition": {"const": "PRESERVE_VERBATIM"}}},
                    "then": {"required": ["preserveCanonicalSource", "provenanceRole"],
                             "properties": {"preserveCanonicalSource": {"const": True}, "provenanceRole": {"const": "FROZEN_REPORT_SNAPSHOT"}}},
                }]},
            },
        },
        "acceptanceRules": [
            "Every frozen tracked blob has a coverage route and exact blob/hash binding.",
            "Every semantic text value has an owner and resolved classification/disposition. A carrier boundary may instead reference the exact closed, independently classified producer set in sourceBoundCarrierRules; this adds no ownership class or translation exemption.",
            "SEMANTIC_REVIEW_REQUIRED is draft-only and never passes acceptance.",
            "User/admin evidence and machine identity are never localized in place.",
            "PRESERVE_VERBATIM for report chrome requires explicit frozen-snapshot provenance and canonical-source preservation; newly generated chrome remains localizable.",
            "Native, runtime, linguistic, canonical and release credit remain false.",
        ],
        "sourceRules": {
            "Swift": "Nested comments, normal/raw/multiline strings, interpolation, String storage declarations, direct and dictionary text parameters/returns of named functions, subscripts and ASCII/Unicode operators, direct and dictionary text initializer parameters, display sinks and separate editable text bindings. No inferred type or native AST claim.",
            "JSON": "Every object key and string leaf; arrays retain their index.",
            "Plist": "Every string key/value; permissions separated from machine schema.",
            "Metadata": "Every nonempty line of Release/docs-product text; structured values are separately inventoried.",
            "Developer": "Whole-document hash and developer-only owner/disposition.",
        },
        "finalCredit": False,
    })


def validate_document(inventory, schema, expected=None, require_resolved=True):
    """Validate ownership invariants, then exact independent source regeneration.

    Draft integrity is deliberately separate from acceptance: a complete census
    with unknown ownership can pass integrity while failing this default gate.
    """
    for document in (inventory, schema):
        if document.get("payloadDigest") != sha(canonical({k: v for k, v in document.items() if k != "payloadDigest"})):
            raise ValueError("Artifact payload digest mismatch")
    if schema != schema_document():
        raise ValueError("Disposition schema differs from the versioned validator contract")
    if inventory.get("schema") != "V30TextBearingSurfaceInventoryV1" or inventory.get("cardID") != CARD:
        raise ValueError("Wrong inventory/card identity")
    if inventory.get("sourceHead") != BASE or not re.fullmatch(r"[a-f0-9]{40}", inventory.get("sourceTree", "")):
        raise ValueError("Wrong frozen source identity")
    if inventory.get("dispositionSchemaPayloadDigest") != schema["payloadDigest"]:
        raise ValueError("Inventory/schema binding mismatch")
    if inventory.get("finalCredit") is not False or inventory.get("nativeEvidence") != "NOT_EXECUTED_NO_NATIVE_CREDIT":
        raise ValueError("Inventory cannot confer final or native credit")
    paths, ids, unresolved, count = set(), set(), 0, 0
    if not isinstance(inventory.get("files"), list) or not inventory["files"]:
        raise ValueError("Missing source census")
    for source in inventory["files"]:
        if not set(schema["requiredFileFields"]).issubset(source):
            raise ValueError("Missing required source fields")
        path = source["path"]
        if not isinstance(path, str) or not path or path in paths or ".." in pathlib.PurePosixPath(path).parts or pathlib.PurePosixPath(path).is_absolute():
            raise ValueError("Invalid or duplicate source path")
        paths.add(path)
        for field, length in (("blobOID", 40), ("sha256", 64)):
            if not re.fullmatch(r"[a-f0-9]{" + str(length) + "}", source[field]):
                raise ValueError("Invalid source hash")
        if type(source["bytes"]) is not int or source["bytes"] < 0 or source["mode"] not in ("100644", "100755"):
            raise ValueError("Invalid source size/mode")
        if not source["owner"] or not source["coverageRoute"] or not isinstance(source["items"], list):
            raise ValueError("Missing source ownership/coverage")
        validate_mixed_flows(source)
        for item in source["items"]:
            count += 1
            if not set(schema["requiredItemFields"]).issubset(item):
                raise ValueError("Missing required item fields")
            if item["recordRole"] != RECORD_ROLES.get(item["kind"]):
                raise ValueError("Source record role does not match its kind")
            for field in ("owner", "locator", "kind", "ownershipEvidence"):
                if not isinstance(item[field], str) or not item[field].strip():
                    raise ValueError("Missing text ownership/evidence")
            expected_id = sha((path + "\0" + item["kind"] + "\0" + item["locator"]).encode())[:24]
            if item["id"] in ids or item["id"] != expected_id:
                raise ValueError("Duplicate or invalid item identity")
            ids.add(item["id"])
            if not re.fullmatch(r"[a-f0-9]{64}", item["sourceTextSHA256"]) or not isinstance(item["preview"], str) or len(item["preview"]) > 180:
                raise ValueError("Invalid text binding/preview")
            classification, disposition = item["classification"], item["disposition"]
            if classification is None:
                if disposition == "SEMANTIC_REVIEW_REQUIRED":
                    unresolved += 1
                elif disposition != VARIANT_DISPOSITION:
                    raise ValueError("Unresolved classification disguised as resolved")
            elif disposition not in CLASS_DISPOSITIONS.get(classification, []):
                raise ValueError("Invalid classification/disposition pair")
            if classification == "REPORT_EXPORT_CHROME" and disposition == "PRESERVE_VERBATIM" and (
                    item.get("preserveCanonicalSource") is not True or item.get("provenanceRole") != "FROZEN_REPORT_SNAPSHOT"):
                raise ValueError("Frozen report chrome requires canonical snapshot provenance")
            review = item.get("semanticReview")
            if review and (review.get("sourceSHA256") != source["sha256"] or not review.get("rule")):
                raise ValueError("Stale semantic source binding")
        source_items = {item["id"]: item for item in source["items"]}
        for item in source["items"]:
            for field in ("sourceItemID", "parentLiteralID"):
                if field in item and source_items.get(item[field], {}).get("kind") != "SWIFT_STRING":
                    raise ValueError("Dangling or non-literal source ownership link")
            if item["kind"] == "STRING_INTERPOLATION_VALUE" and "parentLiteralID" not in item:
                raise ValueError("Interpolation value lacks its source template")
            if item["kind"] in INLINE_CLOSURE_KINDS | {INLINE_CLOSURE_TUPLE_KIND}:
                if (not isinstance(item.get("ownershipBoundary"), str) or not item["ownershipBoundary"].strip()
                        or any(type(item.get(field)) is not int or item[field] < 1 for field in ("line", "column"))):
                    raise ValueError("Inline closure lacks exact source context")
                function_fields = ("parentFunctionSymbol", "parentCallableKind", "parentParameterIndex", "parentParameterSymbol", "parentExternalLabel")
                if item.get("closureParentKind") == "FUNCTION_PARAMETER":
                    if (any(not isinstance(item.get(field), str) or not item[field].strip()
                            for field in ("parentFunctionSymbol", "parentParameterSymbol", "parentExternalLabel"))
                            or item.get("parentCallableKind") not in {"FUNCTION", "INITIALIZER", "SUBSCRIPT", "OPERATOR"}
                            or type(item.get("parentParameterIndex")) is not int or item["parentParameterIndex"] < 0
                            or "parentStorageSymbol" in item):
                        raise ValueError("Inline closure lacks unambiguous function parameter context")
                elif item.get("closureParentKind") == "STORAGE_DECLARATION":
                    if (not isinstance(item.get("parentStorageSymbol"), str) or not item["parentStorageSymbol"].strip()
                            or any(field in item for field in function_fields)):
                        raise ValueError("Inline closure lacks unambiguous storage context")
                else:
                    raise ValueError("Inline closure lacks a supported parent context")
                if item["kind"] == "INLINE_CLOSURE_TEXT_PARAMETER_DECLARATION":
                    if type(item.get("closureParameterIndex")) is not int or item["closureParameterIndex"] < 0:
                        raise ValueError("Inline closure input lacks its slot index")
                    labels = ("closureParameterSymbol", "closureParameterExternalLabel")
                    if any(field in item for field in labels) and any(
                            not isinstance(item.get(field), str) or not item[field].strip() for field in labels):
                        raise ValueError("Inline closure input labels are incomplete")
                elif any(field in item for field in ("closureParameterIndex", "closureParameterSymbol", "closureParameterExternalLabel")):
                    raise ValueError("Inline closure result cannot have an input slot")
                if item["kind"] == INLINE_CLOSURE_TUPLE_KIND:
                    if (type(item.get("elementIndex")) is not int or item["elementIndex"] < 0
                            or ("elementLabel" in item and (not isinstance(item["elementLabel"], str) or not item["elementLabel"].strip()))
                            or any(field in item for field in ("functionSymbol", "callableKind", "typealiasSymbol",
                                                              "parameterIndex", "symbol", "externalLabel"))):
                        raise ValueError("Inline closure tuple result lacks an independent element context")
                elif any(field in item for field in ("elementIndex", "elementLabel")):
                    raise ValueError("Scalar inline closure slot cannot claim tuple element context")
            if item["kind"] == "TYPEALIAS_CLOSURE_TEXT_PARAMETER_DECLARATION":
                if (any(not isinstance(item.get(field), str) or not item[field].strip()
                        for field in ("typealiasSymbol", "ownershipBoundary")) or
                        any(type(item.get(field)) is not int or item[field] < 1 for field in ("line", "column")) or
                        type(item.get("parameterIndex")) is not int or item["parameterIndex"] < 0):
                    raise ValueError("Closure-alias text parameter lacks exact source context")
            if item["kind"] == "TYPEALIAS_TUPLE_TEXT_ELEMENT_DECLARATION":
                if (any(not isinstance(item.get(field), str) or not item[field].strip()
                        for field in ("typealiasSymbol", "ownershipBoundary")) or
                        any(type(item.get(field)) is not int or item[field] < 1 for field in ("line", "column")) or
                        type(item.get("elementIndex")) is not int or item["elementIndex"] < 0 or
                        ("elementLabel" in item and (not isinstance(item["elementLabel"], str) or not item["elementLabel"].strip()))):
                    raise ValueError("Tuple-alias text element lacks exact source context")
            if item["kind"] == "FUNCTION_TUPLE_TEXT_ELEMENT_DECLARATION":
                if (any(not isinstance(item.get(field), str) or not item[field].strip()
                        for field in ("functionSymbol", "ownershipBoundary"))
                        or item.get("callableKind") not in {"FUNCTION", "SUBSCRIPT", "OPERATOR"}
                        or any(type(item.get(field)) is not int or item[field] < 1 for field in ("line", "column"))
                        or type(item.get("elementIndex")) is not int or item["elementIndex"] < 0
                        or ("elementLabel" in item and (not isinstance(item["elementLabel"], str) or not item["elementLabel"].strip()))
                        or any(field in item for field in ("parameterIndex", "symbol", "externalLabel", "typealiasSymbol"))):
                    raise ValueError("Function tuple result lacks exact source context")
            if item["kind"] in {"FUNCTION_TEXT_PARAMETER_DECLARATION", "FUNCTION_TEXT_RETURN_DECLARATION"}:
                if (any(not isinstance(item.get(field), str) or not item[field].strip()
                        for field in ("functionSymbol", "ownershipBoundary")) or
                        any(type(item.get(field)) is not int or item[field] < 1 for field in ("line", "column"))):
                    raise ValueError("Function text declaration lacks exact source context")
                if item["kind"] == "FUNCTION_TEXT_PARAMETER_DECLARATION" and (
                        any(not isinstance(item.get(field), str) or not item[field].strip()
                            for field in ("symbol", "externalLabel")) or
                        type(item.get("parameterIndex")) is not int or item["parameterIndex"] < 0):
                    raise ValueError("Function text parameter lacks exact parameter context")
            if "callableKind" in item or item.get("functionSymbol") in {"init", "subscript"}:
                callable_kind, symbol = item.get("callableKind"), item.get("functionSymbol")
                valid = ((callable_kind == "INITIALIZER" and symbol == "init" and item["kind"] == "FUNCTION_TEXT_PARAMETER_DECLARATION")
                         or (callable_kind == "SUBSCRIPT" and symbol == "subscript")
                         or (callable_kind == "OPERATOR" and isinstance(symbol, str) and re.fullmatch(SWIFT_OPERATOR_PATTERN, symbol))
                         or (callable_kind == "FUNCTION" and item["kind"] == "FUNCTION_TUPLE_TEXT_ELEMENT_DECLARATION"
                             and symbol not in {"init", "subscript"} and re.fullmatch(r"(?:`[^`\r\n]+`|[^\W\d]\w*)", symbol)))
                if not valid or item["kind"] not in {"FUNCTION_TEXT_PARAMETER_DECLARATION", "FUNCTION_TEXT_RETURN_DECLARATION", "FUNCTION_TUPLE_TEXT_ELEMENT_DECLARATION"}:
                    raise ValueError("Special callable text record lacks exact callable context")
            if "textTypeShape" in item and (item["textTypeShape"] not in {"DICTIONARY", "COLLECTION"} or item["kind"] not in {
                    "FUNCTION_TEXT_PARAMETER_DECLARATION", "FUNCTION_TEXT_RETURN_DECLARATION"}):
                raise ValueError("Composite text record lacks exact callable shape")
            if item["kind"] in {"FUNCTION_TEXT_PARAMETER_DECLARATION", "FUNCTION_TEXT_RETURN_DECLARATION"}:
                # Preview is capped at 180 code points. Complete short type
                # spellings can enforce shape intrinsically; longer records
                # are bound by the full regenerated expected source record.
                preview = item["preview"]
                if len(preview) < 180:
                    shape = ("DICTIONARY" if dictionary_text_type_end(preview, 0) == len(preview)
                             else "COLLECTION" if collection_text_type_end(preview, 0) == len(preview) else None)
                    if shape != item.get("textTypeShape"):
                        raise ValueError("Callable composite type and shape disagree")
            if item["kind"] == "TEXT_INPUT_BINDING":
                parent = source_items.get(item.get("parentPresentationID"), {})
                if (parent.get("kind") != "TEXT_PRESENTATION_CALL" or
                        parent.get("symbol") not in {"TextField", "SecureField", "TextEditor"} or
                        item.get("symbol") != parent.get("symbol") or
                        item.get("consumerArgumentLabel") != "text" or
                        type(item.get("consumerArgumentIndex")) is not int or item["consumerArgumentIndex"] < 0):
                    raise ValueError("Editable value lacks an exact text-control binding")
            if "sourceItemID" in item and (item["kind"] != "TEXT_PRESENTATION_CALL" or item.get("consumerArgumentIndex") != 0):
                raise ValueError("Literal label binding must name the exact display argument")
    if type(inventory.get("unresolvedOwnershipCount")) is not int or inventory["unresolvedOwnershipCount"] != unresolved:
        raise ValueError("Unresolved ownership count does not match records")
    expected_status = "DRAFT_REQUIRES_SEMANTIC_REVIEW" if unresolved else "READY_FOR_STATIC_VALIDATION"
    if inventory.get("status") != expected_status:
        raise ValueError("Status disguises unresolved ownership")
    if expected is not None and inventory != expected:
        raise ValueError("Inventory does not exactly reproduce the frozen source census and reviewed rules")
    if require_resolved and unresolved:
        raise ValueError(f"Inventory is not accepted: {unresolved} ownership records remain unresolved")
    return {"result": "STATIC_ACCEPTANCE_PASS" if require_resolved else "DRAFT_INTEGRITY_PASS_NOT_ACCEPTED",
            "files": len(paths), "items": count, "unresolvedOwnershipCount": unresolved,
            "nativeEvidence": "NOT_EXECUTED_NO_NATIVE_CREDIT", "finalCredit": False}


def inventory_bytes(value):
    # One compact JSON record per line keeps a large, exhaustive inventory
    # reviewable without repeated indentation consuming most of its size.
    header = {k: v for k, v in value.items() if k != "files"}
    lines = [json.dumps(header, ensure_ascii=False, indent=2, sort_keys=True)[:-2] + ',\n  "files": [']
    for index, source in enumerate(value["files"]):
        entry = {k: v for k, v in source.items() if k != "items"}
        lines.append("    " + json.dumps(entry, ensure_ascii=False, sort_keys=True)[:-1] + ', "items": [')
        lines.extend("      " + json.dumps(item, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
                     + ("," if number + 1 < len(source["items"]) else "")
                     for number, item in enumerate(source["items"]))
        lines.append("    ]}" + ("," if index + 1 < len(value["files"]) else ""))
    lines.append("  ]\n}\n")
    raw = "\n".join(lines).encode()
    if json.loads(raw) != value:
        raise ValueError("Inventory serialization changed data")
    return raw


def assert_card9_generation_authority():
    task = json.loads(re.search(r"\x60{3}json\n(.*?)\n\x60{3}", (ROOT / TASK).read_text(encoding="utf-8"), re.S)[1])
    if task["cardID"] != CARD or git("rev-parse", "HEAD").decode().strip() != BASE:
        raise ValueError("Generation requires the exact Card9 authority head")
    allowed = {row["path"] for row in task["fence"]["allowedPaths"]}
    if not {INVENTORY, SCHEMA}.issubset(allowed):
        raise ValueError("Inventory paths are not in the exact current fence")


def self_test():
    # Match build_inventory's catalog context so Swift fixtures exercise the
    # same frozen catalog-key classification rules as the real source tree.
    CATALOG_KEYS.clear()
    for catalog_path in ["FieldEvidenceApp/Resources/Localizable.xcstrings",
                         "FieldEvidenceApp/InfoPlist.xcstrings"]:
        CATALOG_KEYS.update(json.loads(git("show", BASE + ":" + catalog_path))["strings"])
    function_vectors = [
        ('func title(_ value: String) {}', [('title', 'value', 0)], []),
        ('func labels(primary title: Swift.String?, tags: [String] = []) async throws -> LocalizedStringKey? {}', [('labels', 'title', 0), ('labels', 'tags', 1)], ['labels']),
        ('protocol P { func copy(_ text: LocalizedStringKey) -> [LocalizedStringKey] }', [('copy', 'text', 0)], ['copy']),
        ('func f<T: Sendable>(_ text: String, from source: LocalizedStringKey) -> [Swift.String]? where T: Equatable { [] }', [('f', 'text', 0), ('f', 'source', 1)], ['f']),
        ('@MainActor func optional(_ value: String?) -> (String, Int) { fatalError() }', [('optional', 'value', 0)], []),
        ('let inferred = "text"; let a = "a", b = "b"', [], []),
        ('let callback: (String) -> Void', [], []),
        ('func map(_ transform: @escaping (String) -> Void) -> Void {}', [], []),
        ('func generic<T>(_ value: T) -> T { value }', [], []),
        ('// func hidden(_ text: String) -> String\nlet s = "func fake(_ text: String) -> String"', [], []),
        ('func nested(_ map: Dictionary<String, [String]>, label: String = build<A, B>()) -> Swift.String { label }', [('nested', 'label', 1), ('nested', 'map', 0)], ['nested']),
        ('func compare(_ flag: Bool = a < b, _ text: String) -> String { text }', [('compare', 'text', 1)], ['compare']),
        ('func closure(_ value: String = { f(1, 2) }(), _ other: String...) throws(MyError) -> String? {}', [('closure', 'value', 0), ('closure', 'other', 1)], ['closure']),
        ('protocol P { func first() -> String\nfunc second(_ text: String) -> String\n}', [('second', 'text', 0)], ['first', 'second']),
        ('func maker() -> String.Type {}\nfunc callback() -> (String) -> String {}', [], []),
        ('func value(_ text: borrowing String)\n async\n throws\n ->\n SwiftUI.LocalizedStringKey\n{}', [('value', 'text', 0)], ['value']),
        ('func escaped(`in` value: String, _ `default`: String) -> [SwiftUI.LocalizedStringKey] {}', [('escaped', 'value', 0), ('escaped', '`default`', 1)], ['escaped']),
        ('func λ(_ text: String) -> String {}', [('λ', 'text', 0)], ['λ']),
        ('func `東京`(_ text: String) -> String {}', [('`東京`', 'text', 0)], ['`東京`']),
    ]
    for source, parameters, returns in function_vectors:
        records = swift_items("FieldEvidenceApp/Features/FunctionFixture.swift", source)
        params = [r for r in records if r["kind"] == "FUNCTION_TEXT_PARAMETER_DECLARATION"]
        outputs = [r for r in records if r["kind"] == "FUNCTION_TEXT_RETURN_DECLARATION"]
        assert [(r["functionSymbol"], r["symbol"], r["parameterIndex"]) for r in params] == parameters, source
        assert [r["functionSymbol"] for r in outputs] == returns, source
        for record in params + outputs:
            assert record["classification"] is None and record["disposition"] == "SEMANTIC_REVIEW_REQUIRED"
            start = int(record["locator"].split(":")[1])
            assert source[start:start + len(record["preview"])] == record["preview"]
            assert record["sourceTextSHA256"] == sha(record["preview"].encode())
            assert record["line"] == source[:start].count("\n") + 1
    initializer_vectors = [
        ('struct P { init(_ text: String) {} }', [('text', 0)]),
        ('init?(label: Swift.String?, tags: [String] = []) {}', [('label', 0), ('tags', 1)]),
        ('required init!(_ key: SwiftUI.LocalizedStringKey, values: String...) {}', [('key', 0), ('values', 1)]),
        ('init<T>(source: T, name: LocalizedStringKey) where T: Sendable {}', [('name', 1)]),
        ('init(_ text: String = build<A, B>(), flags: [Int]) async throws {}', [('text', 0)]),
        ('protocol P { init(title: String)\ninit?(other: [Swift.String]?) }', [('title', 0), ('other', 0)]),
        ('init(callback: (String) -> Void, tuple: (String, Int), map: [String: String], value: Box<String>) {}', [('map', 2)]),
        ('init(flag: Bool = a < b, _ text: borrowing String = { f(1, 2) }()) {}', [('text', 1)]),
        ('let a = Type.init(label: String); let b = .init(label: String); self . /* comment */ init(label: String)', []),
        ('func `init`(_ text: String) -> String { text }; deinit {}', []),
        ('// init(_ a: String) {}\nlet s = "init(_ b: String)"; /* init(_ c: String) */', []),
        ('init(`in` value: String, _ `default`: [LocalizedStringKey]) {}', [('value', 0), ('`default`', 1)]),
    ]
    for source, parameters in initializer_vectors:
        records = swift_items("FieldEvidenceApp/Features/InitializerFixture.swift", source)
        initializers = [r for r in records if r.get("callableKind") == "INITIALIZER"]
        assert [(r["symbol"], r["parameterIndex"]) for r in initializers] == parameters, source
        for record in initializers:
            assert record["kind"] == "FUNCTION_TEXT_PARAMETER_DECLARATION" and record["functionSymbol"] == "init"
            assert record["classification"] is None and record["disposition"] == "SEMANTIC_REVIEW_REQUIRED"
            start = int(record["locator"].split(":")[1])
            assert source[start:start + len(record["preview"])] == record["preview"]
            assert record["sourceTextSHA256"] == sha(record["preview"].encode())
    dictionary_vectors = [
        ('init(values: [String: String]) {}', ['[String: String]'], []),
        ('func f(_ values: [String: Int], value: [Int: Swift.String]?) {}', ['[String: Int]', '[Int: Swift.String]?'], []),
        ('func f(values: Swift.Dictionary<Int, SwiftUI.LocalizedStringKey>) {}', ['Swift.Dictionary<Int, SwiftUI.LocalizedStringKey>'], []),
        ('func f(values: [[Int: [Swift.String]]]) {}', ['[[Int: [Swift.String]]]'], []),
        ('init(values: Optional<Array<Dictionary<Int, String?>>>) {}', ['Optional<Array<Dictionary<Int, String?>>>'], []),
        ('init(values: Swift.Optional<Swift.Array<Swift.Dictionary<String, Int>>>) {}', ['Swift.Optional<Swift.Array<Swift.Dictionary<String, Int>>>'], []),
        ('func f(values: [String: Int]...) {}', ['[String: Int]...'], []),
        ('func f(values: [String: Int]!) {}', ['[String: Int]!'], []),
        ('func f() async throws(ErrorType) -> [String: [Int: String]] { [:] }', [], ['[String: [Int: String]]']),
        ('subscript(values: [String: Int]) -> Dictionary<Int, String>? { nil }', ['[String: Int]'], ['Dictionary<Int, String>?']),
        ('func + (lhs: [String: Int], rhs: Self) -> [Int: String] { [:] }', ['[String: Int]'], ['[Int: String]']),
        ('func \u2295 (lhs: [String: Int], rhs: Self) -> [Int: String] { [:] }', ['[String: Int]'], ['[Int: String]']),
        ('protocol P { func first() -> [String: Int]\nfunc second() -> [Int: String]\n}', [], ['[String: Int]', '[Int: String]']),
        ('func f(_ v: [String: Int] = make<A, B>(), label: String) {}', ['[String: Int]'], []),
        ('func f(_ v: [Int: Bool]) -> Dictionary<Int, Data> { [:] }', [], []),
        ('func f(_ v: (String, [String: Int]), c: ([String: Int]) -> Void) {}', [], []),
        ('func f(_ v: Box<[String: Int]>, c: [String: (Int, String)]) {}', [], []),
        ('func f(_ v: Dictionary<String, Int>.Keys) -> [String: Int].Type {}', [], []),
        ('func f(_ v: Dictionary<String>) -> Dictionary<String, Int, Bool> {}', [], []),
        ('func f(_ v: [String:]) -> [String: Int] & Other {}', [], []),
        ('// func f(_ v: [String: Int])\nlet s = "init(v: [String: Int])"', [], []),
        ('func f(_ v: [String: MyModel], p: Swift.Array<String>) {}', ['[String: MyModel]'], []),
    ]
    for source, parameters, returns in dictionary_vectors:
        records = swift_items("FieldEvidenceApp/Features/DictionaryFixture.swift", source)
        rows = [r for r in records if r.get("textTypeShape") == "DICTIONARY"]
        assert [r["preview"] for r in rows if r["kind"] == "FUNCTION_TEXT_PARAMETER_DECLARATION"] == parameters, source
        assert [r["preview"] for r in rows if r["kind"] == "FUNCTION_TEXT_RETURN_DECLARATION"] == returns, source
        assert len({r["id"] for r in records}) == len(records), source
        for row in rows:
            assert row["classification"] is None and row["disposition"] == "SEMANTIC_REVIEW_REQUIRED"
            start = int(row["locator"].split(":")[1])
